reg["assetdelete"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Soft-delete: to the trash. The blob stays; the /library/* route now 404s
        // it (rebuildDeletedAssets in saveAssets), so references go white at once.
        for (const auto& p : msg.value("paths", std::vector<std::string>{}))
            if (json* a = assetFind(srv, p)) (*a)["deleted"] = true;
        saveAssets(srv);
        broadcastAssets(srv);
    }};

reg["assetfolder"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Folder registry ops for the image/model galleries (create/delete/rename).
        const std::string kind = msg.value("kind", std::string());
        const std::string path = msg.value("path", std::string());
        const std::string op = msg.value("op", std::string());
        if (kind.empty() || path.empty()) return;
        auto& folders = srv.assetFolders;
        auto has = [&](const std::string& fp) {
            return std::any_of(folders.begin(), folders.end(), [&](const json& f) {
                return f.value("kind", std::string()) == kind && f.value("path", std::string()) == fp; });
        };
        const std::string prefix = path + "/";
        auto inSubtree = [&](const std::string& fp) { return fp == path || fp.rfind(prefix, 0) == 0; };
        if (op == "create") {
            if (!has(path)) folders.push_back({{"kind", kind}, {"path", path}});
        } else if (op == "delete") {
            // Drop the folder + its sub-folders; move any items in the subtree to
            // this folder's parent (folders are virtual, items must not orphan).
            const std::string parent = path.find('/') == std::string::npos
                ? std::string() : path.substr(0, path.find_last_of('/'));
            std::erase_if(folders, [&](const json& f) {
                return f.value("kind", std::string()) == kind && inSubtree(f.value("path", std::string())); });
            for (json& a : srv.assets)
                if (a.value("kind", std::string()) == kind && inSubtree(a.value("folder", std::string())))
                    a["folder"] = parent;
        } else if (op == "rename") {
            const std::string to = msg.value("to", std::string());
            if (to.empty()) return;
            const std::string toPrefix = to + "/";
            for (json& f : folders)
                if (f.value("kind", std::string()) == kind) {
                    const std::string fp = f.value("path", std::string());
                    if (fp == path) f["path"] = to;
                    else if (fp.rfind(prefix, 0) == 0) f["path"] = toPrefix + fp.substr(prefix.size());
                }
            for (json& a : srv.assets)
                if (a.value("kind", std::string()) == kind) {
                    const std::string fp = a.value("folder", std::string());
                    if (fp == path) a["folder"] = to;
                    else if (fp.rfind(prefix, 0) == 0) a["folder"] = toPrefix + fp.substr(prefix.size());
                }
        }
        saveAssets(srv);
        broadcastAssets(srv);
    }};

reg["assetlist"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        reply(assetsMessage(srv).dump());
    }};

reg["assetmove"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const std::string folder = msg.value("folder", std::string());
        for (const auto& p : msg.value("paths", std::vector<std::string>{}))
            if (json* a = assetFind(srv, p)) (*a)["folder"] = folder;
        saveAssets(srv);
        broadcastAssets(srv);
    }};

reg["assetpurge"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Permanent for THIS table's gallery: drop the row. The blob itself is
        // deliberately left alone.
        //
        // It used to be unlinked here, when the blob was this instance's private
        // file. It is not any more: the cache is shared by every table on the
        // node, so unlinking would evict for all of them — and the bytes are not
        // this table's to destroy in the first place. Deleting them is ttcraft's
        // job, driven by whether anything still references them.
        for (const auto& p : msg.value("paths", std::vector<std::string>{}))
            std::erase_if(srv.assets, [&](const json& a) { return a.value("path", std::string()) == p; });
        // The row is gone, so the path is no longer in deletedAssets, which the
        // /library route checks before serving. Drop the served-asset cache so a
        // purged path stops answering from memory.
        srv.libAssetCache.clear();
        srv.libAssetCacheBytes = 0;
        saveAssets(srv);
        broadcastAssets(srv);
    }};

reg["assetrestore"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        for (const auto& p : msg.value("paths", std::vector<std::string>{}))
            if (json* a = assetFind(srv, p)) (*a)["deleted"] = false;
        saveAssets(srv);
        broadcastAssets(srv);
    }};

reg["assetsave"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Create or update a manifest row (rename / re-folder / register).
        const std::string path = msg.value("path", std::string());
        if (path.empty()) return;
        json* a = assetFind(srv, path);
        if (a) {
            if (msg.contains("name")) (*a)["name"] = msg["name"];
            if (msg.contains("folder")) (*a)["folder"] = msg["folder"];
            if (msg.contains("kind")) (*a)["kind"] = msg["kind"];
        } else {
            srv.assets.push_back({{"path", path}, {"kind", msg.value("kind", std::string("image"))},
                                  {"name", msg.value("name", std::string())},
                                  {"folder", msg.value("folder", std::string())},
                                  {"deleted", false}, {"t", 0}});
            a = &srv.assets.back();
        }
        saveAssetRow(srv, *a); // exactly one row moved
        broadcastAssets(srv);
    }};

reg["cardformat"] = CommandSpec{Cap::Edit, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        auto* object=c.obj();
        if (!object || !tw::applyCardFormat(*object,msg.value("format",std::string()),msg.value("landscape",false))) {
            reply(json{{"type","cardformatresult"},{"ok",false},{"id",id()}}.dump());return;
        }
        c.beginMutation();broadcastProps(srv,id());
        reply(json{{"type","cardformatresult"},{"ok",true},{"id",id()}}.dump());
    }};

reg["click"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!srv.world.object(id())) return;
        if (srv.scripts.fireClick(id(), player)) c.beginMutation(); // a tap on the object
    }};
    for (const auto key : {"numbertyped", "click", "move", "release", "throw", "toss", "counteradd", "countersub", "counterreset",
                           "clockstart", "clockreset", "clockadd", "clocksub", "clockmode", "align", "flip", "rotl", "rotr", "rot180",
                           "setpose", "notetext", "flick", "group", "ungroup", "clipcut", "clippaste", "setvfx", "counterset", "pawnset", "setmodel", "setid"})
        observeMutation(reg.at(key), objectMutationState);

}

