reg["clipcopy"] = CommandSpec{Cap::None, false, /*readOnly=*/true, true, [fillClipboard](CommandContext& c) {
        TW_CMD_LOCALS(c);
        fillClipboard(srv, player, msg);
    }};

reg["clipcut"] = CommandSpec{Cap::Edit, false, false, true, [fillClipboard](CommandContext& c) {
        TW_CMD_LOCALS(c);
        fillClipboard(srv, player, msg);
        if (msg.contains("ids") && msg["ids"].is_array())
            for (const auto& v : msg["ids"]) {
                const tw::ObjectId oid = v.get<tw::ObjectId>();
                if (srv.world.holder(oid) && srv.world.holder(oid) != player) continue; // held by another
                // The clipboard blob already carries any container contents.
                removeObjectCascade(srv, oid, RemoveFlags::Veto | RemoveFlags::FireDestroy, player);
            }
        broadcastGroups(srv); // a cut may have dissolved groups
    }};

reg["clippaste"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        auto it = srv.clipboard.find(player);
        if (it == srv.clipboard.end() || it->second.empty()) return;
        const tw::TableConfig& tc = srv.world.table();
        tw::Vec3 at = vecFromJson(msg.value("position", json()), {0, 0.3f, 0});
        std::map<int, std::vector<tw::ObjectId>> pasted; // source group -> new ids
        json ids = json::array();
        bool refused = false;
        for (const auto& e : it->second) {
            json j = json::parse(e.json, nullptr, /*allow_exceptions=*/false);
            if (j.is_discarded()) continue;
            tw::Vec3 p{at.x + e.offset.x, at.y + e.offset.y, at.z + e.offset.z};
            tw::clampToTable(tc, p);
            const tw::ObjectId nid = spawnObjectFromJson(srv, j, p);
            if (nid) { ids.push_back(nid); if (e.group) pasted[e.group].push_back(nid); }
            else if (!srv.world.canSpawn(1)) refused = true;
        }
        if (refused) // one toast per paste, however many entries were refused
            replySpawnRefused(c);
        bool grouped = false;
        for (auto& [g, members] : pasted)
            if (members.size() >= 2) { srv.world.createGroup(members); grouped = true; }
        if (grouped) broadcastGroups(srv);
        reply(json{{"type", "pasted"}, {"ids", std::move(ids)}}.dump()); // client selects them
    }};

reg["clockstart"] = reg["clockreset"] = reg["clockadd"] = reg["clocksub"] = reg["clockmode"] =
        CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        auto* clk = dynamic_cast<tw::Clock*>(srv.world.object(id()));
        if (!clk) return;
        if (type == "clockstart") clk->setRunning(!clk->running());
        else if (type == "clockreset") { clk->setSeconds(0); clk->setRunning(false); }
        else if (type == "clockadd") clk->setSeconds(clk->seconds() + 60);
        else if (type == "clocksub") clk->setSeconds(clk->seconds() - 60);
        else if (type == "clockmode") clk->setCountingDown(!clk->countingDown());
    }};
    // Every refusal below is a nak: the client renders these actions the frame
    // they are keyed (predict.ts) and glides the pose back on the reply instead
    // of waiting out its expiry.
    CommandSpec rotate{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::Object* obj = c.obj();
        if (!obj) { c.nak(); return; } // gone, or held by another player
        constexpr float kDeg45 = 3.14159265f / 4.0f;
        if (type == "flip") {
            if (srv.scripts.veto(id(), "tryFlip", player)) { c.nak(); return; }
            // `player` is what lets you flip the card you are CARRYING; c.obj()
            // above already turned away anyone reaching into another's hand.
            if (!srv.world.flipObject(id(), player)) { c.nak(); return; } // already flipping
            srv.scripts.fireFlip(id(), player);
        } else { // align / rotl / rotr / rot180 are all rotations
            if (srv.scripts.veto(id(), "tryRotate", player)) { c.nak(); return; }
            if (type == "align") obj->alignToAxes(srv.scripts.alignmentYawAt(id()).value_or(0.0f));
            else obj->rotateYaw(type == "rotl"   ? kDeg45
                                : type == "rotr" ? -kDeg45
                                                 : 4 * kDeg45); // 180
            srv.scripts.fireRotate(id(), player);
        }
    }};

