reg["containerempty"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        json* items = itemsOf(srv, id());
        if (!o || !items || items->empty()) return;
        if (srv.scripts.veto(id(), "tryDraw", player)) return;
        // Refuse BEFORE erasing the contents: the entries spawn later from the
        // pendingDrops queue, and a cap refusal at drain time can only requeue.
        if (!ensureCanSpawn(c, items->size()))
            return;
        c.beginMutation();
        const tw::Vec3 p = o->position();
        const tw::Vec3 he = o->halfExtents();
        const tw::TableConfig& tc = srv.world.table();
        const auto now = std::chrono::steady_clock::now();
        const std::size_t n = items->size();
        const long long stepMs = n ? std::min<long long>(60, 4000 / (long long)n) : 60;
        const float radius = std::max(he.x, he.z) + 0.06f + float(n) * 0.004f;
        for (std::size_t i = 0; i < n; ++i) {
            const float a = 6.2831853f * float(i) / float(n);
            tw::Vec3 at{p.x + std::cos(a) * radius, p.y + he.y + 0.02f,
                        p.z + std::sin(a) * radius};
            tw::clampToTable(tc, at, 0.05f);
            srv.pendingDrops.push_back({now + std::chrono::milliseconds(std::size_t(i) * stepMs),
                                        at, (*items)[i].dump(), id(), player});
        }
        srv.containerItems.erase(id());
        reply(containerListJson(srv, id(), json::array(), player).dump());
        containerChanged(srv, id());
    }};
    for (const auto key : {"containerset", "containertake", "containername", "containerput", "containerreorder", "containerempty"})
        reg.at(key).commitsMutation = true;

}

