reg["containerlist"] = CommandSpec{Cap::None, false, /*readOnly=*/true, /*vetoable=*/false,
                                       [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        if (!o) return;
        if (hiddenFrom(srv, id(), player)) {
            reply(json{{"type", "contlist"}, {"id", id()}, {"ok", false},
                       {"reason", "hidden"}}.dump());
            return;
        }
        // A deck's contents are hidden information, so who looks is public — the
        // same "N is looking at this" everyone already gets from a close-up. A bag
        // is not secret in TTS and needs no announcement.
        if (dynamic_cast<const tw::Deck*>(o))
            publish(srv, Chan::State,
                    json{{"type", "viewing"}, {"id", id()}, {"player", player}}.dump());
        reply(containerListJson(srv, id(), msg.value("path", json::array()), player).dump());
    }};

reg["containername"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const json path = msg.value("path", json::array());
        const int n = msg.value("n", -1);
        std::string name = msg.value("name", std::string());
        if (name.size() > 120) name.resize(120);
        Level lv = levelAt(srv, id(), path);
        if (!lv.arr || lv.cards || n < 0 || n >= int(lv.arr->size())) return;
        json& entry = (*lv.arr)[std::size_t(n)];
        json& vis = entry["visual"];
        if (!vis.is_object()) vis = json::object();
        if (vis.value("label", std::string()) == name) return;
        c.beginMutation();
        if (name.empty()) vis.erase("label");
        else vis["label"] = name;
        reply(containerListJson(srv, id(), path, player).dump());
        containerChanged(srv, id());
    }};

reg["containerput"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::ObjectId target = msg.value("target", 0u);
        if (!containerPut(srv, target, id(), player)) {
            // The client sends this INSTEAD of a release (input/pointer.ts arms
            // one gesture or the other), so a refusal — a full bag, a Lua veto, a
            // grouped or hand-owned piece — would leave the object hanging in the
            // air, still held by a hand that has already let go. World::release
            // is a no-op unless this player really is the holder.
            if (srv.world.holder(id()) == player) c.beginMutation();
            srv.world.release(id(), player);
            return;
        }
        c.beginMutation();
        reply(containerListJson(srv, target, json::array(), player).dump());
    }};

    // Move an entry within the stack — the order the container hands things out
    // in. Top level only: a nested level is a view of a blob, and re-ordering
    // through a view is the kind of thing that reads fine and desynchronises.

reg["containerreorder"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
