reg["counterset"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::Object* o = c.obj();
        if (!o) return;
        ObjectVisual& vis = srv.visuals[id()];
        const bool wantsConfig = msg.contains("counter") || msg.contains("min")
                                 || msg.contains("max") || msg.contains("step")
                                 || msg.contains("show");
        if (wantsConfig && !can(srv, player, Cap::Edit)) {
            c.replyError("err.noPermission", {{"action", "counterset"}, {"cap", "edit"}});
            return;
        }
        // Turning it OFF is the only branch that ends without a counter, and it
        // is unconditional: unlike a bag, a number has no contents to strand.
        // (An explicit `false` only; a non-bool `counter` is neither on nor off.)
        if (auto on = msg.find("counter"); on != msg.end() && on->is_boolean() && !on->get<bool>()) {
            if (!vis.counter.is_object()) return;
            vis.counter = json();
            if (vis.type.empty()) vis.type = kindToType(o->kind());
            srv.markPropsDirty(id());
            return;
        }
        // The record to edit: the stored one, or a fresh default set — which is
        // what `counter: true` from the properties/workbench side means. A
        // `delta` aimed at an object with no counter is ignored rather than
        // creating one: ± is Cap::Play, and creating is not.
        const bool had = vis.counter.is_object();
        // Type-checked, never json::value(): that THROWS type_error.302 when the
        // key exists with another type, so `{"counter": 1}` from any client would
        // have thrown out of the middle of the command (the same bug class the
        // sanitizers were hardened against).
        const auto onIt = msg.find("counter");
        const bool wantsNew = onIt != msg.end() && onIt->is_boolean() && onIt->get<bool>();
        if (!had && !wantsNew) return;
        json next = had ? vis.counter : sanitizeCounter(json::object());
        // The number as it stood BEFORE anything in this message — read here and
        // not after the config below, so a range edit that clamps the value
        // still reports the real change to the script (max dropped to 5 with 12
        // hit points on the sheet IS a hit, and a delta measured from the
        // already-clamped value would say nothing happened).
        const long long before = had ? next.value("value", 0LL) : 0LL;
        // CONFIG FIRST, then launder, then the value: a range edit and a value
        // edit in one message have to agree, and the delta below multiplies by
        // `step`, which must be the laundered one — a client sending
        // `{step: 0.4, delta: -1}` would otherwise multiply by a 0 that the
        // sanitizer is about to floor to 1.
        for (const char* k : {"min", "max", "step"})
            if (auto it = msg.find(k); it != msg.end() && it->is_number()) next[k] = *it;
        if (auto it = msg.find("show"); it != msg.end() && it->is_string()) next["show"] = *it;
        next = sanitizeCounter(next); // idempotent; whole numbers from here on
        if (auto it = msg.find("value"); it != msg.end() && it->is_number())
            next["value"] = *it;
        if (auto it = msg.find("delta"); it != msg.end() && it->is_number()
                                         && std::isfinite(it->get<double>())) {
            // `delta` counts STEPS, not units: the client sends ±1 and the
            // object's own step decides what that means, so a counter authored
            // in fives cannot be nudged by one from a stale menu.
            const long long steps =
                (long long)std::llround(std::clamp(it->get<double>(), -1e6, 1e6));
            next["value"] = before + steps * next.value("step", 1LL);
        }
        json clean = sanitizeCounter(next);
        if (clean.is_null()) return; // cannot happen (next is an object), belt and braces
        const long long after = clean.value("value", 0LL);
        const bool changed = !had || clean != vis.counter;
        vis.counter = std::move(clean);
        if (vis.type.empty()) vis.type = kindToType(o->kind());
        if (!changed) return;
        srv.markPropsDirty(id());
        // onCounterChange(value, delta, player) — fired only when the NUMBER
        // moved, so a range or display edit does not read as a hit.
        if (after != before || !had)
            srv.scripts.fireEventNum(id(), "counterChange", after, after - before, player);
    }};
