    // Deal `n` cards face-down into EVERY seated player's hand, round-robin —
    // one card each per round, the way a hand is actually dealt, so a deck that
    // runs out mid-deal leaves the earlier seats one ahead rather than the first
    // player holding everything. The single-object `draw` above is the other
    // half of the pair: one card, face down, beside the deck.
    //
    // Cap::Play (dealing is play, not editing), and the deck's own `tryDraw`
    // veto still applies — a script that forbids drawing forbids dealing too.

reg["deal"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!deck()) return;
        const tw::ObjectId did = id();
        if (srv.scripts.veto(did, "tryDraw", player)) return;
        const int n = std::clamp(msg.value("n", 1), 1, 10);
        std::vector<tw::PlayerId> seats;
        seats.reserve(srv.players.size());
        for (const auto& [pid, info] : srv.players) seats.push_back(pid);
        if (seats.empty()) return;
        // A deal has an ORDER, and srv.players is an unordered map — without
        // this the same command dealt a different card to a different seat on
        // every run, which is exactly what a shuffled deck must not depend on.
        std::sort(seats.begin(), seats.end());
        if (!ensureCanSpawn(c, seats.size() * std::size_t(n)))
            return;
        const CardSkin skin = captureSkin(srv, did); // before the deck is consumed
        bool dealt = false, empty = false;
        for (int k = 0; k < n && !empty; ++k)
            for (const tw::PlayerId pid : seats) {
                if (!srv.world.object(did)) { empty = true; break; }
                const auto created = srv.cards.drawCard(did, /*reveal=*/false,
                                                        /*besideDeck=*/false);
                if (created.empty()) { empty = true; break; }
                for (tw::ObjectId nid : created) registerCardVisual(srv, nid, skin);
                srv.handOwnerSet(created.front(), pid);
                dealt = true;
            }
        if (!srv.world.object(did)) srv.visuals.erase(did); // the deck ran dry
        // Once, at the end: arrangeHand re-lays a whole fan and sendReveals
        // builds a private message per socket, so doing either per CARD turned
        // a ten-round deal into eighty broadcasts.
        if (!dealt) return;
        c.beginMutation();
        for (const tw::PlayerId pid : seats) arrangeHand(srv, pid);
        sendReveals(srv);
    }};

