reg["editlock"] = CommandSpec{Cap::Edit, false, true, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Lazily, here and at join/leave: expiry has no deadline of its own, and
        // the tick is the one place that must stay free of per-session work.
        bool changed = pruneEditLocks(srv);
        const std::string action = msg.value("action", std::string());
        const std::string key = msg.value("key", std::string());
        const bool all = action == "releaseAll";
        if (!all && (key.empty() || key.size() > 256 ||
                     key.find_first_of("\r\n") != std::string::npos)) {
            c.replyError("err.badArg", {{"action", std::string(type)}});
            return;
        }
        const auto now = std::chrono::steady_clock::now();
        auto it = srv.editLocks.find(key);
        const bool mine = it != srv.editLocks.end() && it->second.player == player;
        if (all) {
            for (auto i = srv.editLocks.begin(); i != srv.editLocks.end();) {
                if (i->second.player == player) { i = srv.editLocks.erase(i); changed = true; }
                else ++i;
            }
            reply(json{{"type", "editlock"}, {"ok", true}, {"key", key}}.dump());
        } else if (action == "release") {
            // Only the holder releases. Someone else's stale editor is the TTL's
            // problem, not a button anybody gets.
            if (mine) { srv.editLocks.erase(it); changed = true; }
            reply(json{{"type", "editlock"}, {"ok", mine}, {"key", key}}.dump());
        } else if (action == "renew") {
            if (mine) it->second.touched = now;
            reply(json{{"type", "editlock"}, {"ok", mine}, {"key", key}}.dump());
        } else if (action == "acquire") {
            if (it != srv.editLocks.end() && !mine) {
                auto pit = srv.players.find(it->second.player);
                const std::string by =
                    pit != srv.players.end() ? pit->second.name : it->second.name;
                reply(json{{"type", "editlock"}, {"ok", false}, {"key", key},
                           {"by", by}, {"byId", it->second.player}}.dump());
                c.replyError("err.assetLocked", {{"name", by}});
            } else {
                // Re-acquiring one's own key is the renew path: refresh `touched`,
                // and say nothing to anyone — the lease list did not move.
                changed = changed || !mine;
                Server::EditLock& lock = srv.editLocks[key];
                lock.player = player;
                lock.name = srv.players.count(player) ? srv.players[player].name : std::string();
                lock.touched = now;
                reply(json{{"type", "editlock"}, {"ok", true}, {"key", key}}.dump());
            }
        } else {
            c.replyError("err.badArg", {{"action", std::string(type)}});
            return;
        }
        if (changed)
            broadcastEditLocks(srv);
    }};
    for (const auto key : {"setcolor", "setnick", "setperms"}) reg.at(key).commitsMutation = true;
    const auto policyState = [](Server& s) {
        return json{{"spawn", s.policy.spawn}, {"lock", s.policy.lock}, {"drawColor", s.policy.drawColor},
                    {"enabled", s.handsEnabled}, {"disableUnused", s.handsDisableUnused},
                    {"hiding", s.handsHiding}, {"gmExcluded", s.gmExcluded}};
    };
    observeMutation(reg.at("setpolicy"), policyState);
    observeMutation(reg.at("sethands"), policyState);
    reg.at("resettable").commitsMutation = true; // import replaces history itself

}

