reg["effectsave"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Create or update a custom effect. No id (or unknown id) => new copy.
        const std::string wantId = msg.value("id", std::string());
        json* existing = wantId.empty() ? nullptr : effectFind(srv, wantId);
        // Symmetry with the object library: a locked (read-only) entry can't be
        // overwritten. None are seeded today, but the guard keeps a stale/crafted
        // save from clobbering one should built-ins ever ship as data.
        if (existing && existing->value("locked", false)) {
            reply(json{{"type", "effectresult"}, {"id", wantId}, {"ok", false},
                       {"error", "locked"}}.dump());
            return;
        }
        json item = existing ? *existing : json::object();
        item["id"] = existing ? wantId : effectNewId(srv);
        item["name"] = msg.value("name", std::string("Effect"));
        item["category"] = msg.value("category", std::string("Custom"));
        if (msg.contains("spec")) item["spec"] = msg["spec"]; // opaque client FxSpec

        if (existing) *existing = item;
        else srv.effects.push_back(item);
        saveEffectItem(srv, item);
        broadcastEffects(srv);
        reply(json{{"type", "effectresult"}, {"id", item["id"]}, {"ok", true}}.dump());
    }};
    // Soft-delete: move to the bin (deleted=true). Referencing objects stop
    // rendering the effect (a deleted ref resolves to nothing) but keep the ref,
