reg["flick"] = CommandSpec{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::Object* obj = c.obj();
        if (!obj) return;
        if (srv.scripts.veto(id(), "tryFlick", player)) return;
        double dx = msg.value("dx", 0.0), dz = msg.value("dz", 0.0);
        const double n = std::sqrt(dx * dx + dz * dz);
        // Formula shared with the client's flick prediction (throw_predict.ts
        // flickVelocity) — values in protocol/physics.mjs.
        const double power = std::clamp(msg.value("power", 0.0), 0.0, double(tw::tune::kFlickMax));
        if (n < 1e-6 || power <= 0.0) return;
        const tw::Vec3 v{float(dx / n * power), tw::tune::kFlickLift, float(dz / n * power)};
        const tw::Vec3 w = msg.contains("w")
                               ? clampLen(vecFromJson(msg["w"]), tw::tune::kMaxThrowSpin)
                               : srv.world.rollReleaseTumble(id(), v);
        // throwObject (not a bare setLinearVelocity pair): it also registers the
        // pending first-impact kick, which a flicked die deserves exactly as much
        // as a thrown one — and with the client's `ks` the thrower's prediction
        // draws the identical kick.
        srv.world.throwObject(id(), v, w, std::uint32_t(msg.value("ks", 0.0)));
        achievementThrow(srv, player, id(), msg);
        lookaheadOnThrow(srv, id()); // a flick flies too — future records to laggy clients
        srv.scripts.fireEvent(id(), "flick", player);
    }};
