reg["gather"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!heldByOther()) {
            std::vector<tw::Vec3> sources;
            // A selection gathers exactly its stacks; a lone click gathers
            // the proximity pile around the object.
            std::optional<tw::ObjectId> result;
            const auto candidates=msg.contains("ids")&&msg["ids"].is_array()?msg["ids"].get<std::vector<tw::ObjectId>>():srv.cards.gatherCandidates(id());
            const auto combined=combineSkins(srv,candidates);
            if(!combined){c.replyError("atlas.tooMany");return;}
            if (msg.contains("ids")) {
                std::vector<tw::ObjectId> ids;
                for (const auto& v : msg["ids"])
                    ids.push_back(v.get<tw::ObjectId>());
                result = srv.cards.gatherSelected(ids, &sources);
            } else {
                result = srv.cards.gatherStacks(id(), &sources);
            }
            if (result) {
                c.beginMutation();
                // gather consumed a set of stacks; drop every visual whose
                // object is now gone.
                for (auto it = srv.visuals.begin(); it != srv.visuals.end();)
                    it = srv.world.object(it->first) ? std::next(it)
                                                     : srv.visuals.erase(it);
                // Cosmetic fly-in: every client animates ghost cards from
                // each consumed stack into the new deck.
                const tw::Object* res = srv.world.object(*result);
                if (res) {
                    const tw::Vec3 to = res->position();
                    json from = json::array();
                    for (const tw::Vec3& p : sources)
                        from.push_back({p.x, p.y, p.z});
                    publish(srv, Chan::State,
                            json{{"type", "fx"}, {"fx", "gather"}, {"id", *result},
                                 {"to", {to.x, to.y, to.z}}, {"from", from}}
                                .dump());
                }
            }
        }
    }};

