reg["grab"] = CommandSpec{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!c.obj() || srv.world.holder(id()) == player) return;
        if (srv.scripts.veto(id(), "tryGrab", player)) return; // script may forbid grabbing
        // A hand card can only be grabbed by its owner; doing so takes it out
        // of the hand (others' hand cards are not grabbable).
        auto ho = srv.handOwner.find(id());
        if (ho != srv.handOwner.end()) {
            if (ho->second != player)
                return;
            c.beginMutation();
            const tw::PlayerId owner = ho->second;
            srv.handOwnerErase(id()); // keeps handNonCards in sync (iterator dies here)
            if (srv.world.grab(id(), player))
                srv.scripts.fireDrag(id(), player);
            arrangeHand(srv, owner);
            sendReveals(srv);
        } else if (srv.world.grab(id(), player)) {
            c.beginMutation();
            srv.scripts.fireDrag(id(), player); // script "drag" handler
            // Carry companions and reply with their grab-time poses so the client
            // drives the whole formation. A grouped object always carries its
            // group (the weld also keeps it rigid in physics); otherwise, if the
            // client asked for the stack, carry the resting pile on top. (Cards
            // don't ask for a stack — they slide out alone.)
            std::vector<tw::ObjectId> carry;
            if (auto g = srv.world.groupOf(id())) {
                for (tw::ObjectId mid : srv.world.groupMembers(*g))
                    if (mid != id()) carry.push_back(mid);
            } else if (msg.value("stack", false)) {
                carry = restingStack(srv, id());
            }
            json members = json::array();
            for (tw::ObjectId mid : carry) {
                if (srv.scripts.veto(mid, "tryGrab", player)) continue;
                if (srv.world.grab(mid, player)) {
                    srv.scripts.fireDrag(mid, player);
                    const tw::Vec3 p = srv.world.object(mid)->position();
                    members.push_back(json{{"id", mid}, {"x", p.x}, {"y", p.y}, {"z", p.z}});
                }
            }
            if (!members.empty())
                reply(json{{"type", "grabstack"}, {"id", id()}, {"members", members}}.dump());
        }
    }};
    // The browser client sends move as binary tag 6 since protocol v4 (60 Hz per
    // dragged member — skips JSON encode/parse and full-precision doubles). The
