reg["groupmenu"] = CommandSpec{Cap::None, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Menu for a selection: keep actions present in EVERY selected object's
        // menu, dropping slider/option entries (they target a single object with
        // a parameter). A homogeneous selection keeps its whole shared menu; a
        // mixed one keeps only the common base actions.
        std::vector<tw::ObjectId> ids;
        std::vector<const tw::Object*> objs;
        if (msg.contains("ids"))
            for (const auto& v : msg["ids"]) {
                const tw::ObjectId oid = v.get<tw::ObjectId>();
                ids.push_back(oid);
                if (const tw::Object* o = srv.world.object(oid))
                    objs.push_back(o);
            }
        // What ONE member offers. The same contributors the single menu runs,
        // minus the two that cannot mean anything for a selection: the tablet's
        // viewer/editor (one window, one board) and the object's own script
        // items (a per-object callback has no group form). Running only the base
        // menu here is why "To hand", "Pin down", "To library" and "Contents…"
        // were impossible on a multi-selection.
        auto memberEntries = [&](const tw::Object* o) {
            json es = json::array();
            // proximityGather=false: see menuBase. A selection's Gather collects
            // what is SELECTED, so the entry survives on composition alone and
            // the intersection below is what decides — it keeps gather exactly
            // when every member is a card or a deck.
            menuBase(srv, o->id(), o, player, es, /*proximityGather=*/false);
            menuHandAndStates(srv, o->id(), o, player, es);
            menuContainer(srv, o->id(), player, es);
            es.push_back({{"action", "tolib"}, {"icon", "library"}, {"category", "actions"}});
            return es;
        };
        json entries = json::array();
        if (!objs.empty()) {
            const json first = memberEntries(objs.front());
            std::vector<std::map<std::string, json>> others;
            for (std::size_t i = 1; i < objs.size(); ++i) {
                std::map<std::string, json> byAction;
                for (const json& e : memberEntries(objs[i]))
                    byAction.emplace(e.value("action", std::string()), e);
                others.push_back(std::move(byAction));
            }
            for (const json& e : first) {
                // Parameterised kinds address ONE object with one number.
                if (e.contains("slider") || e.contains("options"))
                    continue;
                const std::string a = e.value("action", std::string());
                const bool toggle = e.value("toggle", false);
                bool shared = true;
                for (const auto& m : others) {
                    auto it = m.find(a);
                    // A toggle whose members disagree has no honest tick to
                    // draw — it would show the first one's state and apply to
                    // all of them. Agreeing ones (three unlocked pieces) are
                    // exactly the case "Pin down on a selection" is for.
                    if (it == m.end() ||
                        (toggle && it->second.value("checked", false) != e.value("checked", false))) {
                        shared = false;
                        break;
                    }
                }
                if (shared) entries.push_back(e);
            }
            // gatherSelected needs two stacks to collect into one. A one-member
            // "selection" is the single-object menu's job, proximity rule and
            // all — offering the selection form there would promise a gather
            // that returns nullopt.
            if (objs.size() < 2 || std::any_of(objs.begin(),objs.end(),[&](const tw::Object* o) {
                    return !tw::sameCardSize(*objs.front(),*o);
                }))
                dropGather(entries);
            filterMenuForPlayer(srv, player, entries);
            sortMenuByCategory(entries);
        }
        json out = {{"type", "menu"}, {"ids", ids}, {"entries", std::move(entries)}};
        if (msg.contains("tag"))
            out["tag"] = msg["tag"];
        if (auto request = msg.find("requestId"); request != msg.end() && request->is_number_integer())
            out["requestId"] = *request;
        reply(out.dump());
    }};
    for (const auto key : {"hotkey", "scriptmenu", "uiaction", "ribbonaction", "panelaction", "dialogresult", "pickresult", "setscript", "resumescript", "setglobalscript"})
        observeMutation(reg.at(key), objectMutationState);

