reg["libdelete"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const std::string delId = msg.value("id", std::string());
        // Read-only built-ins can't be deleted (and would re-seed anyway).
        if (const json* it = libFind(srv, delId); it && it->value("locked", false)) return;
        std::erase_if(srv.library, [&](const json& it) { return it.value("id", std::string()) == delId; });
        srv.libraryChanged();
        deleteLibraryItem(srv, delId);
        broadcastLibrary(srv);
    }};

    // ---- client-rendered thumbnail cache ----------------------------------
    // The first browser to render a library preview pushes the PNG here, so every
    // later browser gets the tile for free instead of downloading the (up to
    // 50 MB) model behind it. Design + threat model: scratchpad/atlas-design.md.
    //
    // Upload rides the WS command registry rather than an HTTP route because
    // handleCommand is the ONE place capabilities are checked — HTTP routes have
    // no player identity at all, and an unauthenticated writer into a cache every
    // browser renders is exactly what must not exist. Serving stays anonymous
    // HTTP (/library/thumbs/*), like every other blob.
    //
    // Gate profile, and why it is NOT the asset-command profile: a cache write is
    // not a game action. Declaring Cap::Edit in the spec would run it through the
    // registry's game-action gates as well — the Global script's onPlayerAction
    // veto, the mute freeze, and the turn lock — and every one of those is absurd
    // for "this browser already drew a picture of a library tile": the cache would
    // silently stop filling while it is not your turn. So: Cap::None + readOnly
    // (never forks the time machine) + vetoable=false, and the Edit requirement is
    // enforced right here instead, as `spawn` does for its own policy check.

reg["liblist"] = CommandSpec{Cap::None, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        reply(libraryMessage(srv).dump());
    }};
    // Uploaded-asset manifest (assets.cpp): the workbench Images/Models galleries.
    // `assetlist` replies with the whole manifest + folder registry; the client
    // filters by kind and trash flag. Mutations broadcast `assets` to everyone.

reg["libsave"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Create or update a user template. No id (or unknown id) => new copy.
        const std::string wantId = msg.value("id", std::string());
        json* existing = wantId.empty() ? nullptr : libFind(srv, wantId);
        // A read-only built-in (e.g. the seeded candle) can't be overwritten — the
        // client offers "duplicate" instead. Guards against a stale/crafted save.
        if (existing && existing->value("locked", false)) {
            reply(json{{"type", "libresult"}, {"requestId",msg.value("requestId",0)}, {"id", wantId}, {"ok", false},
                       {"error", "locked"}}.dump());
            return;
        }
        json item = existing ? *existing : json::object();
        item["id"] = existing ? wantId : libNewId(srv);
        item["name"] = msg.value("name", std::string("Object"));
        item["category"] = msg.value("category", std::string("Custom"));
        if (msg.contains("kind")) item["kind"] = msg["kind"];
        if (msg.contains("textures")) item["textures"] = msg["textures"];
        if (msg.contains("script")) item["script"] = msg["script"];
        if (msg.contains("props")) item["props"] = msg["props"];
        // The NON-SCALAR half of the allow-list, which stays a literal: the model
        // path and the two flat float arrays, the deck art lists, the deck's pack
        // discriminator, the multistate list and the tablet document.
        for (const char* k : {"model", "hull", "modelRotation",
                              "back", "backs", "faces", "names", "deckType", "cardAtlas",
                              "states", "tablet",
                              // Kind state a spawn rebuilds the object from, not a
                              // look: the number a Counter / Clock is showing. (The
                              // Note's text is a scalar and rides the table below.)
                              "value", "seconds",
                              "contents",
                              // Authored snap points (chessboard squares, tray slots).
                              // NOT an ObjectVisual field — they live in the script
                              // engine, per object (setObjectSnapsJson), which is why
                              // neither registry below can carry them and libsavefrom
                              // reads them from there. One literal, deliberately.
                              "snaps",
                              "set"})
            if (msg.contains(k)) item[k] = msg[k]; // prop skin + orientation + deck art + kind state + states + tablet doc + snaps + multi-piece set
        // …plus every SCALAR the field table allows into a template
        // (visual_fields.h): the whole PBR surface, the label, the die type, the
        // two render flags and the Note's text. Stored VERBATIM, like a mixin
        // blob — an entry authored against a newer client keeps what it sent.
        for (const VisualField& f : visualFieldTable())
            if (f.libSave && msg.contains(f.key)) item[f.key] = msg[f.key];
        // …plus every registered MIXIN key (visual_mixins.h: `container`,
        // `dieGeo`, `collider`, `stand`, `pdf`, `overlay`, `vfx`), appended
        // programmatically so a new one rides templates without a second literal
        // to forget. Stored VERBATIM: the laundry runs where the blob becomes an
        // OBJECT (spawn / snapshot restore), so an entry authored against a newer
        // client keeps whatever it sent.
        for (const MixinDef& m : mixinRegistry())
            if (msg.contains(m.key)) item[m.key] = msg[m.key];
        // The one thing that is not verbatim, and it is a REMOVAL rather than a
        // rewrite: a mixin key whose value is the "there isn't one" sentinel is
        // dropped instead of stored. "Back to the auto hull" arrives as an
        // explicit `collider: null` (the editor's empty part list), "remove the
        // stand" as `stand: null`, and "no grid" as `overlay: null`/`{}` from the
        // tablet editor when the grid tool was turned off — each has to REMOVE
        // what the template already had, and a stored null is a thing every
        // export and snapshot would then carry around for ever.
        for (const MixinDef& m : mixinRegistry())
            if (item.contains(m.key) && !m.authored(item[m.key])) item.erase(m.key);
        migrateLibraryItemTablet(item); // the doc a client sent may still be v1

        if(item.value("kind",std::string())=="deck") {
            const auto faces=item.value("faces",json::array()),backs=item.value("backs",json::array());
            if(!faces.is_array()||!backs.is_array()||faces.size()>255||(!backs.empty()&&!faces.empty()&&backs.size()!=faces.size())) {
                reply(json{{"type","libresult"},{"requestId",msg.value("requestId",0)},{"id",wantId},{"ok",false},{"error","invalid_card_art"}}.dump());return;
            }
        }

        if(item.value("kind",std::string())=="token"){item["kind"]="prop";if(!item.contains("token"))item["token"]=json::object();}
        if(item.contains("token")) {
            const auto token=sanitizeToken(item["token"]);
            if(!token.is_object()||item.value("kind",std::string())!="prop") {reply(json{{"type","libresult"},{"requestId",msg.value("requestId",0)},{"id",wantId},{"ok",false},{"error","token.invalid"}}.dump());return;}
            item["token"]=token;item["collider"]=tokenColliderJson(token);
            item.erase("model");item.erase("modelRotation");item.erase("stand");item.erase("pawn");
        }
        if (existing) *existing = item;
        else srv.library.push_back(item);
        srv.libraryChanged();
        saveLibraryItem(srv, item);
        broadcastLibrary(srv);

        // Apply the template's visual edits (names, skins) to instances already
        // on the table so changes show up live. Visual-only fields; geometry-
        // affecting ones (model/hull/scale/rotation) need a re-drop, skipped.
        // The instances go out as ONE props message: a set template re-skinned
        // on a laid-out board is dozens of objects, and one message per object
        // is dozens of full-table fan-outs for a single save.
        const std::string tid = item["id"].get<std::string>();
        std::vector<tw::ObjectId> touched;
        std::vector<tw::ObjectId> tokenReshape;
        for (auto& [oid, v] : srv.visuals) {
            if (v.name != tid) continue;
            // The two below come from the MESSAGE, not from `item`: a template
            // edit that says nothing about them must leave the instances alone.
            // A label is per-INSTANCE (uniqueLabel gives every copy its own
            // "Меч 2"), so re-stamping the template's would rename them all back;
            // and `vfx` is EmptyRemoves, so a blanket reset is broadcast AND
            // snapshotted — permanent. The sentinel-removal loop above has
            // already dropped a cleared `vfx: []` from `item`, which is why only
            // the message can still tell "cleared" from "not part of this save".
            if (msg.contains("label")) v.label = msg.value("label", std::string());
            readCardArt(v, item);  // back/faces/names
            readTextures(v, item); // full re-skin (absent keys reset)
            readMaterial(v, item);
            // Through the mixin's sanitizer, like every other path where a
            // template blob becomes an OBJECT's — an empty list is how "the last
            // effect was removed" reaches the instances.
            if (msg.contains("vfx")) {
                json fx = sanitizeVfx(msg["vfx"]);
                v.vfx = fx.is_array() ? std::move(fx) : json::array();
            }
            if(msg.contains("token")&&item.contains("token")){
                if(v.collider!=item["collider"]||!v.model.empty()||v.stand.is_object()||v.pawn.is_object())tokenReshape.push_back(oid);
                v.token=item["token"];v.collider=item["collider"];v.model.clear();v.modelRotation.clear();v.stand=json();v.pawn=json();
            }
            touched.push_back(oid); // live-updates authored effects on instances too
        }
        for(auto oid:tokenReshape)if(auto* object=srv.world.object(oid)) {
            const float bottom=object->position().y-object->halfExtents().y;
            const auto snap=objectSnapshotJson(srv,object);replaceObjectFromJson(srv,oid,snap);
            if(auto* updated=srv.world.object(oid)){auto pos=updated->position();pos.y=std::max(0.0f,bottom)+updated->halfExtents().y;updated->setPosition(pos);}
        }
        broadcastProps(srv, touched);
        reply(json{{"type", "libresult"}, {"requestId",msg.value("requestId",0)}, {"id", item["id"]}, {"ok", true}}.dump());
    }};

reg["libsavefrom"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Snapshot a live object into a NEW template (always a copy).
        const tw::Object* o = srv.world.object(id());
        if (o) {
            json item;
            item["id"] = libNewId(srv);
            item["name"] = msg.value("name", std::string("Object"));
            item["category"] = msg.value("category", std::string("Custom"));
            item["kind"] = kindToType(o->kind());
            if (auto it = srv.visuals.find(id()); it != srv.visuals.end()) {
                const ObjectVisual& v = it->second;
                if (!v.textures.empty()) item["textures"] = v.textures; // raw paths
                if (!v.model.empty()) item["model"] = v.model;
                // Every SCALAR the object AUTHORED, on the field table's template
                // policy (visual_fields.h) — the whole PBR surface, the label, the
                // die type, the two render flags and a Note's text, each omitted
                // while it sits at its documented default. A template has no old
                // value to un-tell (unlike the props channel, which emits the
                // physical bundle's zeros on purpose), so what was never chosen is
                // simply not stored; readMaterial reads the rest back at spawn, so
                // a saved die comes back with the numbers it was saved with.
                //
                // FieldGate::Glass is the one non-obvious rule the rows carry:
                // ior/thickness/dispersion/attenuation* are captured only when the
                // object really is glass (transmission > 0), exactly as the
                // hand-written nest here always did.
                const FieldGates gates = fieldGates(v);
                for (const VisualField& f : visualFieldTable())
                    if (gates.open(f.libGate) && fieldEmits(f, f.lib, v))
                        fieldWrite(f, v, item);
                if (!v.hull.empty()) item["hull"] = v.hull; // prop collider
                if (v.modelRotation.size() == 3) item["modelRotation"] = v.modelRotation;
                if (!v.cardBack.empty()) item["back"] = v.cardBack;
                if (!v.cardBacks.empty()) item["backs"] = v.cardBacks;
                if (!v.cardFaces.empty()) item["faces"] = v.cardFaces;
                if (!v.cardNames.empty()) item["names"] = v.cardNames;
                // Every registered MIXIN blob the live object carries
                // (visual_mixins.h): the authored `collider` and `stand`,
                // `dieGeo` (a user-supplied die's shape and face values),
                // `container` (containerness + its flags + the authored mouth
                // preview), a `pdf` page, the `overlay` grid and the authored
                // `vfx`. AUTHORED ones only: the empty blob that means "this was
                // removed" is a message to live clients, not something a template
                // should carry a copy of. The container's bespoke extra (its
                // contents) follows below.
                for (const MixinDef& m : mixinRegistry())
                    if (m.authored(v.*m.field)) item[m.key] = v.*m.field;
                if (!v.states.empty()) item["states"] = v.states; // multistate variants
                if (v.tablet.is_object()) item["tablet"] = v.tablet; // tablet UI document
                if (v.container.is_object()) {
                    // Contents travel too, so "a bag of dice" is one library item.
                    // The entries are already full object records — the same ones a
                    // snapshot stores — and the export's asset rewrite walks them
                    // (exportGameFiles rewriteObjectAssets), so a mini inside one
                    // ships with its model.
                    if (auto ci = srv.containerItems.find(id());
                        ci != srv.containerItems.end() && ci->second.is_array()
                        && !ci->second.empty())
                        item["contents"] = ci->second;
                }
            }
            // Kind state no ObjectVisual holds, read off the object itself. A
            // deck's PACK is knowable only from its cards — there is no stored
            // deckType anywhere, it is a spawn-time discriminator — so the
            // piquet pack is recognised by its code SET (a saved deck has
            // usually been shuffled, and a dealt-from one is no longer that
            // pack at all).
            if (const auto* deck = dynamic_cast<const tw::Deck*>(o)) {
                std::vector<std::uint8_t> cards = deck->cards(), pack = tw::deck32();
                std::sort(cards.begin(), cards.end());
                std::sort(pack.begin(), pack.end());
                if (cards == pack) item["deckType"] = "piquet32";
            } else if (const auto* cnt = dynamic_cast<const tw::Counter*>(o)) {
                if (cnt->value() != 0) item["value"] = cnt->value();
            } else if (const auto* clk = dynamic_cast<const tw::Clock*>(o)) {
                if (clk->seconds() != 0) item["seconds"] = clk->seconds();
            }
            const std::string script = srv.scripts.getScript(id());
            if (!script.empty()) item["script"] = script;
            // Snap points authored ON this object (chessboard squares, tray
            // slots): local coordinates, so they mean the same thing on every
            // copy the template later spawns.
            if (json snaps = json::parse(srv.scripts.objectSnapsJson(id()), nullptr, false);
                snaps.is_array() && !snaps.empty())
                item["snaps"] = std::move(snaps);
            item["props"] = templateProps(o);
            srv.library.push_back(item);
            srv.libraryChanged();
            saveLibraryItem(srv, item);
            broadcastLibrary(srv);
            reply(json{{"type", "libresult"}, {"requestId",msg.value("requestId",0)}, {"id", item["id"]}, {"ok", true}}.dump());
        }
    }};

