reg["lock"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Editors always lock/unlock; ordinary players only if the GM granted it.
        if (!can(srv, player, Cap::Edit) && !srv.policy.lock) {
            c.replyError("err.noPermission", {{"action", type}, {"cap", "lock"}});
            return;
        }
        if (c.obj()) {
            const bool on = msg.value("on", true);
            if (srv.world.isLocked(id()) == on) return;
            c.beginMutation();
            srv.world.setLocked(id(), on); // pin/unpin in place
            srv.scripts.fireEvent(id(), on ? "lock" : "unlock", player);
        }
    }};
    // Weld a set of objects into one rigid group (>= 2 free objects). The whole
