reg["menu"] = CommandSpec{Cap::None, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* obj = srv.world.object(id());
        if (!obj && id() != 0)
            return; // a stale id: no menu, and nothing to say about it
        json entries = json::array();
        if (obj) {
            menuBase(srv, id(), obj, player, entries);
            menuHandAndStates(srv, id(), obj, player, entries);
            menuScriptItems(srv, id(), entries);
            // A tablet (scriptable board): the live 2D popup viewer (any player,
            // also on the T hotkey) and the WYSIWYG editor — both client-handled.
            // A PDF-faced slab stops after the reader and the editor (which is
            // where its file, format and kind are changed): the draw toggle has
            // nothing to act on, and it is not a container either, so the two
            // contributors below are skipped for it.
            const bool isPdf = obj->kind() == tw::ObjectKind::Tablet &&
                               menuTablet(srv, id(), obj, player, entries);
            if (!isPdf) {
                menuPawn(srv, id(), player, entries);
                menuContainer(srv, id(), player, entries);
            }
            // Save this object into the library as a reusable template (client-handled).
            entries.push_back({{"action", "tolib"}, {"icon", "library"}, {"category", "actions"}});
            // Every contributor has now had its say — apply the contract.
            filterMenuForPlayer(srv, player, entries);
            sortMenuByCategory(entries);
        } else {
            // Right-click on empty table: the script-contributed table menu (TTS
            // global addContextMenuItem). Each item routes to its owner script.
            if (json mi = json::parse(srv.scripts.tableMenuJson(), nullptr, false); mi.is_array())
                for (const json& e : mi)
                    entries.push_back(menuEntryFromItem(e));
        }
        json out = {{"type", "menu"}, {"id", id()}, {"entries", std::move(entries)}};
        // Echo the request tag so the client can route the response (right-
        // click context menu vs. the ribbon's contextual tab).
        if (msg.contains("tag"))
            out["tag"] = msg["tag"];
        if (auto request = msg.find("requestId"); request != msg.end() && request->is_number_integer())
            out["requestId"] = *request;
        reply(out.dump());
    }};

reg["merge"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::ObjectId target = msg.value("target", 0u);
        const auto targetHolder = srv.world.holder(target);
        const auto* sourceObject=srv.world.object(id());
        const auto* targetObject=srv.world.object(target);
        if (!sourceObject || !targetObject) return;
        if (!tw::sameCardSize(*sourceObject,*targetObject)) {
            if (srv.world.holder(id()) == player) srv.world.release(id(),player);
            return;
        }
        if (!heldByOther() && (!targetHolder || *targetHolder == player)) {
            if (srv.scripts.vetoObj(target, "tryMerge", id(), player)) return; // target may refuse the merge
            if (srv.scripts.vetoObj(target, "tryEnterContainer", id(), player)) return; // container may refuse
            // onObjectEnterContainer(obj, player) on the target while the source is still alive.
            srv.scripts.fireEventObj(target, "objectEnterContainer", id(), player);
            // The result keeps the custom-deck skin of whichever side had one.
            const auto combined=combineSkins(srv,{target,id()});
            if(!combined){srv.world.release(id(),player);c.replyError("atlas.tooMany");return;}
            srv.world.release(id(), player); // the dragged stack leaves the hand
            if (auto result = srv.cards.mergeStacks(target, id())) {
                c.beginMutation();
                srv.visuals.erase(id());
                if (*result != target)
                    srv.visuals.erase(target); // a card target became a deck
                srv.scripts.fireEvent(*result, "merge", player); // onMerge on the surviving stack
                // The ids the merge CONSUMED. They leave the world as ordinary
                // removals, but they did not leave the TABLE - they became
                // *result - so a client that plays a despawn effect on a removal
                // has to cut theirs instead (client scene/spawn_fx silence).
                json gone = json::array();
                if (*result != id()) gone.push_back(id());
                if (*result != target) gone.push_back(target);
                // Clients voice the merge off this: the count delta alone is ambiguous
                // (a whole deck joining reads like a gather) and a card+card merge
                // is a brand-new id.
                publish(srv, Chan::State,
                        json{{"type", "fx"}, {"fx", "merge"}, {"id", *result},
                             {"gone", gone}}.dump());
            }
        }
    }};

