reg["pawnset"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::Object* o = c.obj();
        if (!o || o->kind() != tw::ObjectKind::Prop) return;
        ObjectVisual& vis = srv.visuals[id()];
        // Explicit `false` only: a non-bool `pawn` is neither on nor off, and a
        // PATCH arriving as `{pawn: {...}}` is handled below.
        if (auto on = msg.find("pawn"); on != msg.end() && on->is_boolean() && !on->get<bool>()) {
            if (!vis.pawn.is_object()) return;
            vis.pawn = json();
            if (vis.type.empty()) vis.type = kindToType(o->kind());
            broadcastProps(srv, id());
            return;
        }
        // The record to edit: the stored one, or a fresh default set — which is
        // what `pawn: true` from the workbench / the add menu means.
        const auto onIt = msg.find("pawn");
        const bool wantsNew = onIt != msg.end()
                              && ((onIt->is_boolean() && onIt->get<bool>()) || onIt->is_object());
        if (!vis.pawn.is_object() && !wantsNew) return;
        json next = vis.pawn.is_object() ? vis.pawn : sanitizePawn(json::object());
        // A patch: only the members the message actually names are written, so
        // a live slider never has to echo the two image paths back. `anchor` is
        // merged one axis at a time for the same reason — the gizmo writes x/z
        // while the y field writes y.
        if (onIt != msg.end() && onIt->is_object()) {
            for (auto it = onIt->begin(); it != onIt->end(); ++it) {
                if (it.key() == "anchor") {
                    if (!it.value().is_object()) continue;
                    if (!next["anchor"].is_object()) next["anchor"] = json::object();
                    for (auto a = it.value().begin(); a != it.value().end(); ++a)
                        next["anchor"][a.key()] = a.value();
                } else next[it.key()] = it.value();
            }
        }
        json clean = sanitizePawn(next);
        if (!clean.is_object()) return; // cannot happen (next is an object), belt and braces
        // The pawn's COLLIDER: the base prism plus the plate's extruded outline,
        // derived by the client (pawn.ts pawnColliderSpec — it is the side that
        // knows the model's bounds and has decoded the pictures) and laundered
        // here like any other authored compound. It rides this command rather
        // than a second one because it is not an independent edit: a plate that
        // grew 10 mm and a collider that did not is a piece that collides with
        // something it no longer looks like.
        json nextCol;
        bool wantsCol = false;
        if (auto it = msg.find("collider"); it != msg.end()) {
            wantsCol = true;
            if (it->is_object()) nextCol = sanitizeCollider(*it);
        }
        const bool colChanged = wantsCol && nextCol != vis.collider;
        if (vis.pawn == clean && !colChanged) return;
        vis.pawn = std::move(clean);
        if (vis.type.empty()) vis.type = kindToType(o->kind());
        if (!colChanged) { broadcastProps(srv, id()); return; }
        // A new shape is a new BODY: Jolt builds the compound at spawn, so the
        // object is re-spawned under its own id through the snapshot round trip
        // — the same move `setmodel` makes, and for the same reason (pose, guid,
        // script, scale and lock all survive it).
        vis.collider = nextCol;
        json snap = objectSnapshotJson(srv, o);
        if (!snap.contains("visual") || !snap["visual"].is_object()) snap["visual"] = json::object();
        if (nextCol.is_object()) snap["visual"]["collider"] = nextCol;
        else snap["visual"].erase("collider");
        snap["visual"]["pawn"] = vis.pawn;
        replaceObjectFromJson(srv, id(), snap);
        broadcastProps(srv, id());
    }};

reg["pdfmarks"] = CommandSpec{Cap::None, false, /*readOnly=*/true, /*vetoable=*/false,
                                  [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const std::string key = userBlobKey(srv.players[player]);
        if (key.empty() || !srv.db) return;
        const std::string asset = msg.value("asset", std::string());
        if (asset.empty() || asset.size() > 512) return;
        json all = loadUserBlob(*srv.db, key, "pdfmarks");
        // Fallback read of the pre-account (clientId-keyed) row; the next write
        // re-files everything under the account key.
        if (!all.is_object()) {
            const std::string& cid = srv.players[player].clientId;
            if (key != cid && !cid.empty()) all = loadUserBlob(*srv.db, cid, "pdfmarks");
        }
        if (!all.is_object()) all = json::object();
        if (msg.contains("data")) { // write
            if (msg["data"].is_object()) all[asset] = msg["data"];
            else all.erase(asset);
            saveUserBlob(*srv.db, key, "pdfmarks", all);
        }
        const json mine = all.contains(asset) ? all[asset] : json::object();
        reply(json{{"type", "pdfmarks"}, {"asset", asset}, {"data", mine}}.dump());
    }};
    // Every refusal below answers with a toast rather than returning in silence:
    // six bare `return;`s read at the seat picker as a click that did nothing.
    // "Taken" is the one that needed a key of its own (err.colorTaken) — the
    // rest are a bad argument, or rights, which the catalogue already words.

reg["pdfpage"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        auto it = srv.visuals.find(id());
        if (it == srv.visuals.end() || !it->second.pdf.is_object() || it->second.pdf.empty())
            return;
        json& p = it->second.pdf;
        // The page COUNT is discovered by whichever client parsed the file first
        // and reported it; until then the only bound is sanitizePdf's. Accepting
        // it here (rather than trusting each turn) keeps the clamp in one place.
        if (msg.contains("pages") && msg["pages"].is_number_integer()) {
            const int n = msg["pages"].get<int>();
            if (n > 0 && n <= 100000) {
                p["pages"] = n;
                // The count arriving is the moment an earlier OVERSHOOT becomes
                // provable. Until it does, `page` is clamped against 100000 and
                // a strip held on `›` walks straight past the end of the file;
                // accepting the count without re-clamping the page it disproves
                // left every client showing a page nobody can render, for ever.
                // Doing it here heals it on every client at once.
                if (p.value("page", 1) > n) p["page"] = n;
            }
        }
        if (msg.contains("page") && msg["page"].is_number_integer()) {
            const int last = p.value("pages", 100000);
            p["page"] = std::clamp(msg["page"].get<int>(), 1, std::max(1, last));
        }
        if (msg.contains("book") && msg["book"].is_boolean()) {
            const bool want = msg["book"].get<bool>();
            p["book"] = want;
            // The spread is a PHYSICAL change now, not just a flag: the slab
            // opens like a book, doubling its width about its own spine. The
            // direction is decided by `wide` and NOT by the old `book` — those
            // two can legitimately disagree on a table saved before the fold
            // existed (spread flag set, slab still 1x), and folding on `book`
            // there would halve a slab that was never doubled. Read this way
            // that state simply heals: the first open doubles it for real.
            // When foldObject REFUSES — the slab is being held, or its collider
            // cannot be stretched — the flag still flips and nothing moves,
            // which is precisely what this command did before the fold existed.
            // `wide` then disagrees with `book`, and that state heals itself the
            // same way an old save's does: the next turn ON is a real open.
            //
            // A fold ALREADY RUNNING is always retargeted, whatever `wide`
            // currently says: half way through an open, `wide` is still false,
            // so a plain "does the target differ from the state" test would
            // refuse to reverse exactly the toggle that means "no, shut it
            // again". foldObject flips the direction in place from there.
            const bool wide = p.value("wide", false);
            if ((srv.world.isFolding(id()) || want != wide)
                && srv.world.foldObject(id(), want)) {
                p["fold"] = json{{"dir", want ? "open" : "close"}};
                srv.foldingSlabs.insert(id());
            }
        }
        broadcastProps(srv, id());
    }};

