        // hand it straight to this player so it follows their cursor. Reply
        // with the new id - the client can't otherwise know what it grabbed.
        if (deck()) {
            if (srv.scripts.veto(id(), "tryDraw", player)) return; // tryDraw covers pulling too
            if (!ensureCanSpawn(c, 1))
                return;
