            const auto created = srv.cards.drawCard(id(), /*reveal=*/false,
                                                    /*besideDeck=*/false);
            if (!created.empty()) c.beginMutation();
            for (tw::ObjectId nid : created)
                registerCardVisual(srv, nid, skin);
