reg["release"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const bool held = srv.world.holder(id()) == player;
        // A placement (no client throw velocity) parks the piece at the grab's
        // final target first — the reliable move flushed just ahead of this
        // release retargets the spring, but the spring itself never gets a tick
        // to close the gap, which left every placement short by the spring lag
        // (and off the cell a grid-snapped carry showed). See
        // World::settleReleaseAtTarget for the clamps.
        if (held && !msg.contains("v"))
            srv.world.settleReleaseAtTarget(id(), player);
        srv.world.release(id(), player);
        if (held) {
            // Optional client-authoritative throw ("v"/"w", clamped like the
            // `throw` command below — MUST match its caps): the carry spring
            // keeps braking toward the final move target for another half-RTT
            // after the player already let go, so the server's own release
            // velocity runs low — weak throws flew visibly shorter than the
            // thrower saw (and than the client's local prediction). The
            // client also rolls the tumble axis itself and seeds its
            // prediction with the same vector.
            const bool thrown = msg.contains("v");
            if (thrown) {
                tw::Vec3 v = clampLen(vecFromJson(msg["v"]), tw::tune::kMaxThrowSpeed);
                // …and a DIE always leaves with a slight down-push, never an
                // upward lob (tune::kDieReleaseVyMax — the TTS reference forces
                // vy ≈ −1 u/s at every release; see protocol/physics.mjs
                // throw.dieReleaseVyMax). The client applies the identical clamp
                // to the vector it sends AND to its prediction seed, so on a
                // current client this is a no-op; it is here for legacy clients,
                // scripted releases and hostile ones, which under low gravity
                // could otherwise balloon a die across the table.
                // Deliberately NOT in World::throwObject: the flick path runs
                // through there carrying its own +kFlickLift unstick, and
                // clamping that would break the flick formula the client
                // predicts against.
                if (const tw::Object* o = srv.world.object(id()))
                    if (o->kind() == tw::ObjectKind::Die)
                        v.y = std::min(v.y, tw::tune::kDieReleaseVyMax);
                // Optional client release position "p" — same trust class as
                // v/w/ks. The carry spring lags the client's own spring by
                // ~one-way transit, so the throw otherwise starts ~v·(RTT/2)
                // behind where the thrower saw it, seeding every local-predict
                // and lookahead divergence (the bounce chaos amplifies it).
                // Clamp to the table and to a tight radius around the server
                // pose (scaled by throw speed, capped) so a bad client can't
                // teleport pieces; setPosition keeps orientation + velocity.
                if (msg.contains("p")) {
                    if (tw::Object* obj = srv.world.object(id())) {
                        tw::Vec3 p = vecFromJson(msg["p"], obj->position());
                        tw::clampToTable(srv.world.table(), p);
                        p.y = std::clamp(p.y, tw::tune::kReleaseWarpMinY,
                                         tw::tune::kReleaseWarpMaxY);
                        const tw::Vec3 sp = obj->position();
                        tw::Vec3 d{p.x - sp.x, p.y - sp.y, p.z - sp.z};
                        const float vLen = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
                        const float maxD =
                            std::min(std::max(tw::tune::kReleaseWarpMinD,
                                              vLen * tw::tune::kReleaseWarpPerSpeed),
                                     tw::tune::kReleaseWarpMaxD);
                        d = clampLen(d, maxD);
                        obj->setPosition({sp.x + d.x, sp.y + d.y, sp.z + d.z});
                    }
                }
                // `ks` (v8): the client's per-throw kick seed — its prediction
                // draws the first-impact jitter from the same ThrowKickRng.
                srv.world.throwObject(
                    id(), v,
                    clampLen(vecFromJson(msg.value("w", json())), tw::tune::kMaxThrowSpin),
                    std::uint32_t(msg.value("ks", 0.0)));
                // Marquee-grabbed piles release as N of these commands inside
                // one or two ticks; joinThrowPack turns that burst into one
                // pack whose members don't collide with each other in flight
                // (they were ~54% interpenetrating in hand — the CARRIED layer
                // collides with nothing — and dumping that into the solver at
                // throw speed is what exploded the pack). See World::
                // joinThrowPack; the client's throw prediction mirrors it.
                srv.world.joinThrowPack(id(), player);
                achievementThrow(srv, player, id(), msg);
                lookaheadOnThrow(srv, id()); // future records to laggy clients (thrower incl.)
            }
            // A thrown piece is leaving, not being placed — no snap magnet.
            if (!thrown && msg.value("snap", true)) { // client's point-snap toggle; default on
                // An authored snap POINT wins over a grid cell: it was placed
                // deliberately, the lattice is a default.
                if (!srv.scripts.snapOnDrop(id()))
                    snapDropOnObjectGrid(srv, id()); // ... else the host's overlay grid
            }
            // Placed (not thrown) inside a hand zone => into that hand. A THROWN
            // piece is not being put anywhere in particular, so it stays on the
            // felt even if it happens to come down on someone's patch — same
            // reasoning as the snap magnet above, and it keeps a lobbed token
            // from disappearing into a stranger's hand.
            if (!thrown)
                captureIntoHand(srv, id(), player);
            srv.scripts.fireDrop(id(), player);     // script "drop" handler
        }
    }};

