reg["setcolor"] = CommandSpec{Cap::None, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::PlayerId target = msg.value("id", 0u);
        const std::string color = msg.value("color", "");
        const bool known = std::find(kColors.begin(), kColors.end(), color) != kColors.end();
        if (!known || !srv.players.count(target)) {
            c.replyError("err.badArg", {{"action", std::string(type)}});
            return;
        }
        // Caps-admins manage anyone's color; others only their own.
        const bool admin = can(srv, player, Cap::Admin);
        if (target != player && !admin) {
            c.replyError("err.noPermission", {{"action", std::string(type)}, {"cap", "admin"}});
            return;
        }
        PlayerInfo& tgt = srv.players[target];
        if (tgt.tooling) { c.replyError("err.badArg"); return; }
        const std::string old = tgt.color;
        if (old == color) return; // nothing to do, and nothing to say about it
        const bool toBlack = color == "black";
        // The two ways this can go differ only in what happens BEFORE the shared
        // tail: a handover also has to move the outgoing GM, so it records who
        // that was in `prevGm` and the tail pushes their new colour too.
        tw::PlayerId prevGm = 0;
        if (toBlack && srv.colorUsed("black")) {
            // Held black moves only when the GM HIMSELF hands the seat over, or
            // an OWNER reassigns it (incl. taking it for himself). The recipient
            // gets black (and full manager caps); the old GM takes the
            // recipient's color in return. Admins may not yank a live GM.
            if (!isGm(srv, player) && !can(srv, player, Cap::Owner)) {
                c.replyError("err.noPermission", {{"action", std::string(type)}, {"cap", "owner"}});
                return;
            }
            for (auto& [pid, pp] : srv.players)
                if (pp.color == "black") { prevGm = pid; break; }
            // Neither is reachable from a consistent roster (black is held, and a
            // target already holding it left at `old == color`) — so there is no
            // specific thing to say beyond "that didn't work".
            if (!prevGm || prevGm == target) {
                c.replyError("err.failed");
                return;
            }
            c.beginMutation();
            srv.players[prevGm].color = old;
        } else {
            // Otherwise only a FREE color may be taken — never from its current
            // holder (a disconnected GM frees black; an admin may then claim it).
            if (srv.colorUsed(color)) {
                c.replyError("err.colorTaken");
                return;
            }
            // Black is the GM seat: admins only (claim it yourself, or hand the vacant
            // seat to another). The new GM always becomes a full manager.
            if (toBlack && !admin) {
                c.replyError("err.noPermission", {{"action", std::string(type)}, {"cap", "admin"}});
                return;
            }
        }
        c.beginMutation();
        tgt.color = color;
        srv.syncSeats(); // the colour IS the chair: the player (and a handed-over GM) moves with it
        const bool capsChanged = toBlack && !has(tgt.caps, Cap::Admin);
        if (capsChanged) {
            tgt.caps = tgt.caps | Cap::Admin;
            noteExternalAuthority(tgt.userId, tgt.caps);
            normalizeAuthority(srv);
        }
        broadcastPlayers(srv);
        sendReveals(srv); // the black (GM) seat may have moved -> hand visibility changes
        resendRestrictedTablets(srv); // ... and a colour-restricted element follows the seat
        srv.scripts.fireGlobal("playerChangeColor", target);
        if (capsChanged) srv.scripts.fireGlobal("playerChangeCaps", target);
        if (long long uid = tgt.userId) {
            std::optional<std::string> capsPush;
            if (capsChanged) capsPush = capsCsv(tgt.caps);
            s2sPutPlayer(uid, capsPush, tgt.seat, color);
        }
        // A handover moved the outgoing GM to the recipient's old colour.
        if (prevGm)
            if (long long uid = srv.players[prevGm].userId)
                s2sPutPlayer(uid, std::nullopt, srv.players[prevGm].seat, old);
    }};
