reg["setid"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Set the object's string id (guid / alias) from the dialog: take it if
        // free, else reject with an error the client surfaces. The numeric id
        // (protocol key) is unchanged.
        const tw::ObjectId cur = id();
        std::string newGuid = msg.value("newid", std::string());
        // trim surrounding whitespace
        const auto a = newGuid.find_first_not_of(" \t\r\n");
        const auto b = newGuid.find_last_not_of(" \t\r\n");
        newGuid = (a == std::string::npos) ? std::string() : newGuid.substr(a, b - a + 1);
        tw::Object* obj = srv.world.object(cur);
        bool ok = false;
        std::string err;
        if (heldByOther()) err = "held";
        else if (!obj) err = "gone";
        else if (newGuid.empty()) err = "invalid";
        else if (newGuid == obj->guid()) ok = true; // unchanged
        else if (srv.world.findByGuid(newGuid)) err = "taken";
        else { obj->setGuid(newGuid); ok = true; }
        reply(json{{"type", "setidresult"}, {"id", cur}, {"newid", newGuid},
                   {"ok", ok}, {"error", err}}
