    // that table into the game export, and these must not travel. One blob per
    // user, keyed inside by the PDF's asset path, so opening a document is one read.
    //
    // Cap::None + readOnly: a spectator may annotate their own copy of a manual,
    // and nothing here touches the table, so it must not fork the time machine.

reg["setmodel"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Replace a prop's 3D model + collider (workbench Models tab / object
        // action). Only props have a model; presets are rejected. The collider is
        // rebuilt from the new hull by re-spawning under the same id via the
        // snapshot round trip (pose / guid / script / scale / lock all survive).
        tw::Object* o = c.obj();
        if (!o || o->kind() != tw::ObjectKind::Prop) return;
        json snap = objectSnapshotJson(srv, o);
        if (!snap.contains("visual") || !snap["visual"].is_object()) snap["visual"] = json::object();
        snap["visual"]["model"] = sanitizeAssetPath(msg.value("model", std::string()));
        if (msg.contains("hull")) snap["visual"]["hull"] = msg["hull"];
        // A new model invalidates any collider authored against the OLD one, so an
        // explicit `collider` replaces it and an explicit null clears it back to the
        // auto hull; omitting the key leaves whatever the object already had.
        if (msg.contains("collider")) {
            if (msg["collider"].is_object()) snap["visual"]["collider"] = msg["collider"];
            else snap["visual"].erase("collider");
        }
        // Same for the figurine stand: it was fitted to the old model's footprint
        // and lowest point, so a swap either brings its own or drops it.
        if (msg.contains("stand")) {
            if (msg["stand"].is_object()) snap["visual"]["stand"] = msg["stand"];
            else snap["visual"].erase("stand");
        }
        if (msg.contains("modelRotation")) snap["visual"]["modelRotation"] = msg["modelRotation"];
        replaceObjectFromJson(srv, id(), snap); // respawns under the same id, new collider
        broadcastProps(srv, id());
    }};

reg["setnick"] = CommandSpec{Cap::None, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::PlayerId target = msg.value("id", 0u);
        std::string nick = msg.value("nick", std::string());
        if (!srv.players.count(target) || !sanitizeNick(nick)) {
            c.replyError("err.badArg", {{"action", std::string(type)}});
            return;
        }
        // Caps-admins manage anyone's nickname; others only their own.
        if (target != player && !can(srv, player, Cap::Admin)) {
            c.replyError("err.noPermission", {{"action", std::string(type)}, {"cap", "admin"}});
            return;
        }
        // Impersonation: the client composes "username (nick)", so a nick that
        // reads as somebody ELSE's username puts their name on this seat in
        // every chat line, mention chip and roster row. Their username is also
        // the token an @mention resolves against, which the table cannot undo.
        for (const auto& [pid, p] : srv.players)
            if (pid != target && iequalsAscii(p.name, nick)) {
                c.replyError("err.nickTaken");
                return;
            }
        PlayerInfo& tgt = srv.players[target];
        if (tgt.nick == nick) return; // nothing to do, and nothing to say about it
        c.beginMutation();
        tgt.nick = nick;
        broadcastPlayers(srv);
        // "" is a VALUE here (cleared), not an unset optional — see s2s.h.
        if (long long uid = tgt.userId)
            s2sPutPlayer(uid, std::nullopt, std::nullopt, std::nullopt, nick);
    }};

reg["setoverlay"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        if (!o || !kindTakesOverlay(o->kind()))
            return;
        auto it = msg.find("overlay");
        if (it != msg.end() && !it->is_null() && !it->is_object())
            return;
        ObjectVisual& v = srv.visuals[id()];
        // The grid is authored from the same editor and saved by the same button,
        // so it answers to the same rule (see settabletdoc). Cap::Play at the
        // registry, the per-tablet rule here.
        const bool hadDoc = v.tablet.is_object() && !v.tablet.empty();
        if (hadDoc ? !mayEditTablet(srv, player, v.tablet) : !can(srv, player, Cap::Edit)) {
            c.replyError("err.noPermission", {{"action", "setoverlay"}, {"cap", "edit"}});
            return;
        }
        if (v.type.empty()) v.type = kindToType(o->kind());
        json next = (it == msg.end() || it->is_null()) ? json() : sanitizeOverlay(*it);
        v.overlay = next.is_object() ? std::move(next) : json::object();
        broadcastProps(srv, id());
    }};

    // Switch ONE side's active page. Server-owned like every other tablet value:
    // a tablet on the table is a physical object, so everyone sees the page that
    // is actually face up (see the doc-v2 note in client/src/tablet.ts).

reg["setpdf"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        if (!o || o->kind() != tw::ObjectKind::Tablet) return;
        ObjectVisual& v = srv.visuals[id()];
        if (v.type.empty()) v.type = kindToType(o->kind());
        // An absent/empty `pdf` detaches — the same "empty object means removed"
        // convention the overlay uses.
        json next = msg.contains("pdf") ? sanitizePdf(msg["pdf"]) : json();
        // Both halves must be a REAL attachment: sanitizePdf answers `{}` for an
        // object with no usable asset (the detach sentinel), and merging the old
        // page into that would build a `{page:1}` blob — a PDF with no file,
        // which reads as "attached" everywhere downstream.
        const bool real = next.is_object() && !next.empty();
        const bool had = v.pdf.is_object() && !v.pdf.empty();
        if (real) {
            // WHAT SURVIVES AN ATTACHMENT is decided by what the field is a fact
            // ABOUT. `wide` and `book` describe the OBJECT — how wide the
            // collider actually is, and whether its face shows a spread — so
            // they outlive a file swap; `page` and `pages` describe the FILE, so
            // they go with it and only a re-attach of the same asset keeps them.
            //
            // `wide` in particular is read off the STORED blob and never off the
            // message: it is the server's record that the x2 on props.scale[0]
            // is the spread's doubling, and a client that could set it would be
            // claiming a doubling the shape has not got (whatever sanitizePdf
            // let through is dropped here). Losing it is what let the editor's
            // "replace the document" card leave a physically 2x slab believing
            // it was 1x — after which the next spread toggle opened an already
            // open book and landed on 4x.
            if (had && v.pdf.value("wide", false)) next["wide"] = true;
            else next.erase("wide");
            if (had && !msg["pdf"].contains("book")) next["book"] = v.pdf.value("book", false);
            // Re-attaching the same file keeps where everyone had got to.
            if (had && v.pdf.value("asset", std::string()) == next.value("asset", std::string())) {
                if (!msg["pdf"].contains("page")) next["page"] = v.pdf.value("page", 1);
                if (!next.contains("pages") && v.pdf.contains("pages")) next["pages"] = v.pdf["pages"];
            }
            // A fold in flight belongs to the world, not to the file: the slab
            // goes on tipping whatever is written on its face. `fold` is what
            // holds every client on the single-page texture until it lands, and
            // dropping it here would repaint a spread onto a slab that is still
            // half open. (Server-authored, so it is copied from the stored blob
            // and only while the world agrees it is still running.)
            if (srv.world.isFolding(id()))
                if (auto f = v.pdf.find("fold"); f != v.pdf.end()) next["fold"] = *f;
        } else if (had) {
            detachFold(srv, id(), v); // the doubling comes off with the blob
        }
        v.pdf = next.is_object() ? next : json::object(); // {} = detached, and it broadcasts
        // A PDF and an authored board cannot both own the face.
        if (v.pdf.is_object() && !v.pdf.empty()) v.tablet = json();
        broadcastProps(srv, id());
    }};

reg["setperms"] = CommandSpec{Cap::Admin, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Change another player's capabilities. Reaching here already required
        // Admin (the cap gate), and Owner implies Admin.
        const tw::PlayerId target = msg.value("id", tw::PlayerId(0));
        auto tit = srv.players.find(target);
        if (tit == srv.players.end()) return;
        const Cap requested = parseCaps(msg.value("caps", std::string()));
        // Only an Owner may grant or revoke the Owner role.
        if (has(requested, Cap::Owner) != has(tit->second.caps, Cap::Owner) &&
            !can(srv, player, Cap::Owner)) {
            c.replyError("err.ownerOnlyRole");
            return;
        }
        // Refuse a change that would leave the table with no Owner and no Admin.
        const Cap prev = tit->second.caps;
        tit->second.caps = requested;
        bool anyManager = false;
        for (auto& [pid, p] : srv.players)
            if (has(p.caps, Cap::Owner) || has(p.caps, Cap::Admin)) { anyManager = true; break; }
        if (!anyManager) {
            tit->second.caps = prev; // revert
            c.replyError("err.lastManager");
            return;
        }
        if (prev != tit->second.caps) c.beginMutation();
        noteExternalAuthority(tit->second.userId, tit->second.caps);
        normalizeAuthority(srv); // Owner with no admins regains Admin
        broadcastPlayers(srv);
        resendRestrictedTablets(srv); // "editors"-only elements just changed hands
        // Persist the reassignment to ttcraft so it survives restart (raw bits;
        // parseCaps round-trips them). Does NOT change the user's room role.
        if (long long uid = tit->second.userId)
            s2sPutPlayer(uid, capsCsv(tit->second.caps), std::nullopt, std::nullopt);
        srv.scripts.fireGlobal("playerChangeCaps", target);
    }};
    // GM table policy (the "Настройки стола" panel): grant spawn/lock to ordinary
    // players, or restrict their draw colour. Admin/Owner only. Only the fields
    // present in the message change.

reg["setpolicy"] = CommandSpec{Cap::Admin, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (msg.contains("spawn")) srv.policy.spawn = msg["spawn"].get<bool>();
        if (msg.contains("lock")) srv.policy.lock = msg["lock"].get<bool>();
        if (msg.contains("drawColor")) srv.policy.drawColor = msg["drawColor"].get<bool>();
        broadcastPolicy(srv);
    }};
    // TTS's Options > Hands, as a partial patch. Turning the mechanic off leaves
    // the zones in place as seats — see Server::handsEnabled — so this never
    // disturbs the camera, the nameplates or the seat auto-layout.
    //   {"type":"sethands", "enabled":false, "hiding":"reverse"}

reg["setpose"] = CommandSpec{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::Object* obj = c.obj();
        if (!obj) { c.nak(); return; }
        if (srv.scripts.veto(id(), "trySetpose", player)) { c.nak(); return; }
        bool scaled = false;
        if (msg.contains("pos") && msg["pos"].is_array()) {
            tw::Vec3 p = vecFromJson(msg["pos"], obj->position());
            tw::clampToTable(srv.world.table(), p);
            p.y = std::clamp(p.y, 0.0f, 0.5f);
            obj->setPosition(p);
        }
        if (msg.contains("rot") && msg["rot"].is_array() && msg["rot"].size() == 4)
            obj->setRotation({msg["rot"][0].get<float>(), msg["rot"][1].get<float>(),
                              msg["rot"][2].get<float>(), msg["rot"][3].get<float>()});
        if (msg.contains("scale")) {
            tw::Vec3 s = vecFromJson(msg["scale"], obj->scale());
            // Guard against degenerate shapes only — see kScaleMin's note in
            // protocol/physics.mjs for why the floor is 1e-4 and not 0.05.
            // The client clamps to the same pair (objkeys.ts) so the optimistic
            // local scale matches what comes back confirmed.
            const float cl = tw::tune::kScaleMin, hi = tw::tune::kScaleMax;
            s.x = std::clamp(s.x, cl, hi); s.y = std::clamp(s.y, cl, hi); s.z = std::clamp(s.z, cl, hi);
            obj->setScale(s);
            scaled = true;
        }
        if (scaled) broadcastProps(srv, id()); // scale isn't in the binary pose stream
        srv.scripts.fireEvent(id(), "setpose", player);
    }};
    // Edit a note's text (dblclick editor). Basic play — writing notes is table
    // play like flipping cards, not table editing; the tile itself is still
    // spawned/removed under Edit rules.

reg["setprops"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Edit an object's properties (the object-properties dialog / scripts). Only
        // the fields present in the message are touched; rotations are euler deg.
        //
        // `ids` is the multi-selection form: the SAME patch onto every listed
        // object. One command rather than N because the dialog applies live —
        // dragging a material slider over a 32-piece selection would otherwise be
        // 32 messages and 32 broadcasts per pointer event.
        std::vector<tw::ObjectId> targets;
        if (auto it = msg.find("ids"); it != msg.end() && it->is_array()) {
            for (const json& v : *it)
                if (v.is_number_unsigned()) targets.push_back(v.get<tw::ObjectId>());
        } else {
            targets.push_back(id());
        }
        std::vector<tw::ObjectId> touched;
        for (const tw::ObjectId oid : targets) {
            // Same gate as c.obj(): skip anything a different player is holding.
            const auto holder = srv.world.holder(oid);
            if (holder && *holder != player) continue;
            tw::Object* o = srv.world.object(oid);
            if (!o) continue;
            const json before = objectProps(srv, o);
            // Appearance (render-only, stored in the visual).
            ObjectVisual vis = srv.visuals[oid];
            applyMaterialPatch(vis, msg);
            if (msg.contains("concealable")) vis.concealable = msg["concealable"].get<bool>();
            if (msg.contains("noShadow")) vis.noShadow = msg["noShadow"].get<bool>();
            // The object's display NAME (the hover tooltip, the contents window's
            // row). Empty clears it and the name falls back to the template's.
            if (auto l = msg.find("label"); l != msg.end() && l->is_string()) {
                vis.label = l->get<std::string>();
                if (vis.label.size() > 120) vis.label.resize(120);
            }
            if (msg.contains("noteText") && o->kind() == tw::ObjectKind::Note)
                vis.noteText = msg["noteText"].get<std::string>();
            applyPhysicsProps(o, msg); // complete patch validated before setters
            srv.visuals[oid] = std::move(vis);
            if (before != objectProps(srv, o)) {
                c.beginMutation();
                touched.push_back(oid);
            }
        }
        broadcastProps(srv, touched);
    }};

reg["setscript"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Same primary gate as getscript: only a live object's script is settable
        // here. A missing id — a stale object, the Global id, or the privileged
        // System id — is refused before the engine is touched, with the same
        // "no such object" the engine returns for a genuinely-gone object.
        if (!srv.world.object(id())) {
            reply(json{{"type", "scriptresult"}, {"id", id()},
                       {"ok", false}, {"error", "no such object"}}.dump());
            return;
        }
        const std::string code = msg.value("code", std::string());
        // Record whether the author is an admin: the script engine gates its
        // promote/demote moderation calls on it (a Cap::Edit author must not be
        // able to self-promote via player:promote()).
        const bool authorAdmin = can(srv, player, Cap::Admin);
        const std::optional<std::string> err =
            srv.scripts.setScript(id(), code, /*fireLoad=*/true, authorAdmin);
        if (!err && !code.empty() && srv.scripts.scriptEnabled(id()))
            achievementEvent(srv, player, "script");
        // Persist by guid so the edit survives restarts (empty code clears it).
        if (srv.db && !err.has_value())
            if (const tw::Object* o = srv.world.object(id())) {
                if (code.empty()) delScriptRow(*srv.db, o->guid());
                else setScriptRow(*srv.db, o->guid(), code);
            }
        reply(json{{"type", "scriptresult"},
                   {"id", id()},
                   {"ok", !err.has_value()},
                   {"error", err.value_or("")}}
                  .dump());
    }};
    // Re-enable a script the overload governor suspended (or one that error-
    // disabled) WITHOUT recompiling — the "fix it without a restart" path next
    // to re-saving in the editor. id 0 = the Global script; any other id must be
    // a live object, which keeps the privileged System pseudo-id unreachable
    // exactly like get/setscript above.

reg["setsettings"] = CommandSpec{Cap::None, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const std::string key = userBlobKey(srv.players[player]);
        if (!key.empty() && srv.db && msg.contains("data"))
            saveUserBlob(*srv.db, key, "settings", msg["data"]);
    }};

reg["settabletdoc"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        if (!o || !msg.contains("doc") || !msg["doc"].is_object())
            return;
        ObjectVisual& v = srv.visuals[id()];
        const bool hadDoc = v.tablet.is_object() && !v.tablet.empty();
        if (hadDoc ? !mayEditTablet(srv, player, v.tablet) : !can(srv, player, Cap::Edit)) {
            c.replyError("err.noPermission", {{"action", "settabletdoc"}, {"cap", "edit"}});
            return;
        }
        if (v.type.empty()) v.type = kindToType(o->kind());
        json doc = msg["doc"];
        migrateTabletDoc(doc); // a v1 doc from a script/library lands here too
        // The author only ever saw what their seat is allowed to see, so what
        // comes back is missing the rest — put it back before storing.
        mergeHiddenElements(doc, v.tablet, tabletViewerFor(srv, player));
        // Only the GM writes the access rule. Anyone else's save carries whatever
        // their editor happened to hold, and a grantee could otherwise widen
        // their own rights (or lock the GM's other players out) with one save.
        // `edit` is a doc-ROOT key and mergeHiddenElements only touches
        // `elements`, so the two cannot interfere — the order is free, and this
        // sits after the merge only because that is the order it reads in.
        if (!isGm(srv, player)) {
            if (auto e = v.tablet.find("edit"); e != v.tablet.end()) doc["edit"] = *e;
            else doc.erase("edit");
        }
        v.tablet = std::move(doc);
        // The mirror of `setpdf`'s rule: a PDF and an authored board cannot both
        // own the face. `{}` rather than a null — that is the "detached"
        // sentinel sanitizePdf documents, so the clear actually broadcasts and
        // survives a snapshot round trip (the EmptyRemoves rule,
        // visual_mixins.h); a null would leave every client showing the last
        // page it saw. Empty documents are excluded because that is how the
        // editor CLEARS a board, and clearing a board must not detach a PDF the
        // player never touched.
        if (v.tablet.is_object() && !v.tablet.empty()
            && v.pdf.is_object() && !v.pdf.empty()) {
            // The blob is where `wide` lives, so the spread's doubling comes off
            // the collider with it (detachFold) — including mid-fold, which this
            // command can genuinely land in: the editor's conversion is one save
            // away from a slab that is still tipping.
            detachFold(srv, id(), v);
            v.pdf = json::object();
        }
        broadcastProps(srv, id());
    }};

    // --- PDF-faced tablets -----------------------------------------------------
    //
    // Attach/detach a PDF (Cap::Edit — it changes what the object IS), and turn
    // its pages (Cap::Play — reading is playing). `page`/`book` are SHARED: the
    // slab is a physical object, so everyone at the table sees the same spread.
    // The reader window's own book toggle is a separate, client-only thing.

reg["settabletpage"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        json* doc = tabletDocOf(srv, id());
        if (!doc)
            return;
        json* side = sideOf(*doc, msg.value("side", 0));
        const std::string page = msg.value("page", std::string());
        if (!side || page.empty() || !sideHasPage(*side, page))
            return;
        if (side->value("active", std::string()) == page)
            return;
        (*side)["active"] = page;
        syncNavValues(*doc, msg.value("side", 0));
        broadcastProps(srv, id());
    }};

    // Freehand annotations on a tablet side. Strokes are vectors in page px and
    // live on the side (sides[i].ink), so they persist with the object, ride
    // snapshots, and draw into the same canvas as everything else. They are NOT
    // the world drawing tool's 3D strokes — those float above a surface and
    // never reach the texture.

reg["setvfx"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Edit an object's authored visual effects (workbench Effects tab, live
        // preview on a table instance). `vfx` is the full replacement array; each
        // client reconciles its locally-spawned effects from the props broadcast.
        // Laundered through the mixin's own sanitizer (an inline spec is opaque,
        // but its light is a real light on everyone's table); an absent or
        // unusable list is the empty one, which is how "clear them" travels.
        if (tw::Object* o = c.obj()) {
            (void)o;
            ObjectVisual& vis = srv.visuals[id()];
            json next = msg.contains("vfx") ? sanitizeVfx(msg["vfx"]) : json();
            vis.vfx = next.is_array() ? std::move(next) : json::array();
            broadcastProps(srv, id());
        }
    }};
    // The `counter` mixin: a number riding any object (hit points on a mini,
    // ammo on a token). Its own command rather than a generic mixin setter,
    // because the capability is not uniform (visual_mixins.h policy 3):
    //
    //   * `delta` (in STEPS) and an explicit `value` are PLAYING — Cap::Play at
    //     the registry. Taking 3 damage is a move, not an edit, and requiring
    //     Cap::Edit for it would mean only the GM could ever hit anything.
    //   * `counter` (create/remove) and `min`/`max`/`step`/`show` are AUTHORING
    //     what the object is — Cap::Edit, checked here. A player who may hit a
    //     mini must not be able to widen the range they are clamped by.
    //
    // The value is clamped to [min, max] server-side whatever arrives, and the
    // change fires `onCounterChange(value, delta, player)` on the object's
    // script so a sheet can react to a hit. The broadcast is COALESCED to the
    // next tick (Server::propsDirty): a scripted counter must not put a props
    // message on the wire per simulation step.

reg["shuffle"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (tw::Deck* d = deck()) {
            if (d->count() < 2) return;
            c.beginMutation();
            const auto beforeOrder = d->cards();
            d->shuffle();
            achievementEvent(srv, player, "shuffle", {{"unchanged", beforeOrder == d->cards()}});
            srv.scripts.fireEvent(id(), "shuffle", player);
            // Every client plays the riffle animation on this deck.
            publish(srv, Chan::State,
                    json{{"type", "fx"}, {"fx", "shuffle"}, {"id", id()}}.dump());
        } else if (isContainer(srv, id()) && !heldByOther()) {
            // A bag shuffles its own entries. No riffle fx — that animation is a
            // deck of cards flipping past itself, and it would read as nonsense
            // over a sack.
            if (containerCount(srv, id()) < 2) return;
            c.beginMutation();
            containerShuffle(srv, id());
            srv.scripts.fireEvent(id(), "shuffle", player);
            reply(containerListJson(srv, id(), json::array()).dump());
        }
    }};

reg["snapadd"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // `target` binds the point to an OBJECT (x/y/z then being local to it —
        // a board, a tablet, anything with a flat top); absent = the table.
        // Everything downstream — selection, the batch edits, the clipboard —
        // addresses it by the same stable id either way.
        const tw::ObjectId host = msg.value("target", tw::ObjectId(0));
        const int sid = host ? srv.scripts.addObjectSnap(host, msg.dump())
                             : srv.scripts.addUserSnap(msg.dump());
        reply(json{{"type", "snapresult"}, {"id", sid}}.dump()); // so the client can select it
    }};

reg["snapclear"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        srv.scripts.clearUserSnaps();
    }};
    // Decals (table stamp layer, ribbon "Стол"): add / batch edit (dx,dz delta
    // move + w/rot) / batch delete / clear. Same Cap::Edit gate as zones/points.

reg["snapdel"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        srv.scripts.removeUserSnapNear(msg.value("x", 0.0), msg.value("z", 0.0),
                                       msg.value("radius", 0.04));
