reg["spawn"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Editors always spawn; ordinary players only if the GM granted it.
        if (!can(srv, player, Cap::Edit) && !srv.policy.spawn) {
            c.replyError("err.noPermission", {{"action", type}, {"cap", "spawn"}});
            return;
        }
        tw::Vec3 pos = vecFromJson(msg.value("p", json()),
                                   {srv.frand(-0.4f, 0.4f), 0.3f, srv.frand(-0.3f, 0.3f)});
        // Source of fields: a library template if `template` is given, else the
        // message itself. A "prop" carries a convex hull; others a base kind.
        const std::string tmplId = msg.value("template", std::string());
        const json* tmpl = tmplId.empty() ? nullptr : libFind(srv, tmplId);
        const json& src = tmpl ? *tmpl : msg;

        // The builder is per-OBJECT, so a `set` template (one library entry that
        // yields a whole pile — the classic domino set) just runs it once per
        // piece with that piece's overrides merged in.
        const json over = msg.value("over", json());
        // A 0 return is ambiguous (unknown kind vs. capacity); only count it as
        // a capacity refusal when the world really is refusing right now.
        bool refused = false;
        auto spawnOne = [&](const json& s, tw::Vec3 at) {
            const tw::ObjectId nid = spawnOneObject(srv, s, at, tmplId, over, player,
                                                    tmpl != nullptr);
            if (nid) c.beginMutation();
            if (!nid && !srv.world.canSpawn(1)) refused = true;
            return nid;
        };

        // Global-script trySpawn(params, player): the table script may forbid
        // this spawn (e.g. table limits, turn rules) by returning false. A set
        // is ONE action — vetoed or not as a whole, not 28 times over.
        if (srv.scripts.vetoSpawn(json{{"kind", src.value("kind", "die")},
                                       {"dieType", src.value("dieType", std::string("d6"))},
                                       {"template", tmplId},
                                       {"x", pos.x}, {"y", pos.y}, {"z", pos.z}}
                                      .dump(),
                                  player))
            return;
        if (src.contains("set") && src["set"].is_array() && !src["set"].empty())
            spawnSet(srv, src, pos, spawnOne);
        else
            spawnOne(src, pos);
        if (refused) // one toast per command, even for a partially-spawned set
            replySpawnRefused(c);
    }};

reg["cut"] = reg["split"] = reg["draw"] = reg["reveal"] =
        CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (tw::Deck* d = deck()) {
            const tw::ObjectId did = id();                // the source deck
            if ((type == "draw" || type == "reveal") && srv.scripts.veto(did, "tryDraw", player))
                return; // script may forbid drawing from this deck
            // Capacity check up front, where the refusal can be NAMED — the
            // DeckController's own canSpawn precheck returns the same empty
            // list a bad argument does. Clamp the pile count the way splitDeck
            // will, so an oversized `n` doesn't refuse a legal split near the cap.
            const std::size_t need =
                type == "split"
                    ? std::size_t(std::clamp(msg.value("n", 2), 2, std::max(2, d->count())) - 1)
                    : 1;
            if (!ensureCanSpawn(c, need))
                return;
            const CardSkin skin = captureSkin(srv, did); // before the op may consume the deck
            const auto created =
                type == "cut"     ? srv.cards.cutDeck(did, msg.value("n", 0))
                : type == "split" ? srv.cards.splitDeck(did, msg.value("n", 2))
                                  : srv.cards.drawCard(did, type == "reveal");
            if (!created.empty()) c.beginMutation();
            for (tw::ObjectId nid : created)
                registerCardVisual(srv, nid, skin);
            // onDraw(card, player) on the deck for a draw/reveal (if it survived).
            if ((type == "draw" || type == "reveal") && !created.empty() && srv.world.object(did)) {
                srv.scripts.fireEventObj(did, "draw", created.front(), player);
                // onObjectLeaveContainer(card, player) on the deck (TTS container event).
                srv.scripts.fireEventObj(did, "objectLeaveContainer", created.front(), player);
            }
            if (!srv.world.object(did)) // the original became a single card
                srv.visuals.erase(did);
        }
    }};
    // Deal `n` cards face-down into EVERY seated player's hand, round-robin —
    // one card each per round, the way a hand is actually dealt, so a deck that
    // runs out mid-deal leaves the earlier seats one ahead rather than the first
    // player holding everything. The single-object `draw` above is the other
    // half of the pair: one card, face down, beside the deck.
    //
    // Cap::Play (dealing is play, not editing), and the deck's own `tryDraw`
    // veto still applies — a script that forbids drawing forbids dealing too.

reg["spread"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (tw::Deck* d = deck()) {
            // The deck is destroyed up front and the cards spawn later from the
            // pendingCards queue — refuse HERE, before takeAllCards, when the
            // whole fan cannot fit (net growth is count-1: the deck goes away).
            if (!ensureCanSpawn(c, std::size_t(std::max(1, d->count())) - 1))
                return;
            const tw::Vec3 origin = d->position();
            const tw::Vec3 cardScale = d->scale();
            const bool faceUp = msg.value("mode", "faceup") == "faceup";
            const CardSkin skin = captureSkin(srv, id()); // custom-deck art for each dealt card
            c.beginMutation();
            std::vector<std::uint8_t> cards = srv.cards.takeAllCards(id());
            srv.visuals.erase(id());

            // An even fan around the deck's spot. ~60 ms between cards, but
            // never longer than 4 s total: small hands finish quickly, big
            // ones speed up so the whole spread stays under the cap.
            const auto now = std::chrono::steady_clock::now();
            const std::size_t n = cards.size();
            const long long stepMs = n ? std::min<long long>(60, 4000 / n) : 60;
            const tw::TableConfig& tc = srv.world.table();
            // The radius grows with the card count so each card overlaps only
            // its neighbour by about half its 70 mm width — the fan then
            // settles as a clean spiral, every card resting flat ON the
            // previous with parallel faces a full thickness apart. The old
            // fixed 0.16 m ring packed 52 x 70 mm = 3.3 m of card width onto a
            // 1 m circumference; a closed ring can't expand, so the solver
            // wedged cards INTO each other at one level — nearly-coplanar
            // crossing faces that z-fight from any angle.
            // 42 mm of each card's 105 mm width is left showing — the corner
            // index and then some — which puts 2.5 cards over any spot instead
            // of the 3.3 that 32 mm gave. Depth is what the solver pays for:
            // every layer is another contact pair holding the one below it.
            const float spacing = 0.042f * cardScale.x;
            // And the ring is left OPEN, by a card's width of bare felt between
            // the last card and the first. A CLOSED ring of overlapping cards is
            // a hoop under compression with nowhere to expand: the deal ended in
            // 3 s and the fan then spent another 20 shoving itself into shape,
            // cards creeping tens of millimetres off the circle and popping
            // loose at 0.17 m/s long after it looked finished. An open arc lets
            // that push out through the two free ends instead.
            // (tools/spread_probe.mjs measures exactly this.)
            const float gap = 0.105f * cardScale.x;
            const float maxR = std::max(0.16f, std::min(tc.halfWidth, tc.halfDepth) - 0.10f);
            const float radius = std::min(
                std::max(0.16f, (float(n) * spacing + gap) / (2.0f * 3.14159265f)), maxR);
            // A small table clamps the radius, so clamp the SPAN too: whatever
            // the table forces, the two ends still never close on each other.
            const float span = std::min(
                n > 1 ? float(n - 1) * spacing / radius : 0.0f, 2.0f * 3.14159265f * 0.9f);
            for (std::size_t i = 0; i < n; ++i) {
                const float a = n > 1 ? span * float(i) / float(n - 1) : 0.0f;
                tw::Vec3 p{origin.x + std::cos(a) * radius, 0.012f,
                           origin.z + std::sin(a) * radius};
                tw::clampToTable(tc, p, 0.06f);
                srv.pendingCards.push_back(
                    {now + std::chrono::milliseconds(std::size_t(i) * stepMs),
                     p,
                     3.14159265f / 2.0f - a, // long side points outward
                     cards[n - 1 - i],       // dealt from the top of the deck
                     faceUp, skin.back, skin.faces, skin.names, skin.tid, cardScale, skin.backs});
            }
        }
    }};

