reg["tableplan"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        json report;
        if (msg.value("reset", false)) {
            resetTablePlan(srv);
            report = {{"ok", true}, {"warnings", json::array()}};
        } else if (!msg.contains("plan") || !msg["plan"].is_object()) {
            report = {{"ok", false}, {"error", "plan must be an object"}};
        } else if (msg.value("merge", false)) {
            patchTablePlan(srv, msg["plan"], report);
        } else {
            applyTablePlan(srv, msg["plan"], report);
        }
        report["type"] = "tableplanresult";
        reply(report.dump());
    }};
    // What the table is MADE of, as a partial patch:
    //   {"type":"tablesurface", "surface":{"felt":{"preset":"textile","noise":0.3}}}
    //   {"type":"tablesurface", "reset":true}
    // Same pane and the same cap as tableShape — it is the other half of the
    // table editor — but readOnly, because the blob is not in the snapshot ring
    // (it rides the game/export, like the lighting): forking the time machine on
    // a colour tweak would throw away a redo future that the rollback could not
    // have restored anyway.
    //
    // `reset` is a server-side re-seed, NOT a patch of default values: only the
    // server knows the textures THIS game shipped with, and a client sending
    // {map:""} for "back to normal" would strip the felt the game came with.

reg["tableprops"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::TableConfig& cur = srv.world.table();
        float wh = cur.wallHeight;
        int seats = cur.seats;
        if (msg.contains("wallHeight") && msg["wallHeight"].is_number()) {
            const double v = msg["wallHeight"].get<double>();
            // Floor at 5 mm: the rail is a ribbon, and one thinner than that
            // reads as a seam rather than an edge. Ceiling at 30 cm — past
            // that it hides the felt from a seated camera.
            if (std::isfinite(v)) wh = static_cast<float>(std::clamp(v, 0.005, 0.30));
        }
        if (msg.contains("seats") && msg["seats"].is_number_integer())
            seats = std::clamp(msg["seats"].get<int>(), 0, static_cast<int>(kColors.size()));
        if (wh == cur.wallHeight && seats == cur.seats)
            return; // a spinner re-sending its current value must not fork the ring
        // Cosmetic: no static body depends on either field, so the statics stay
        // and nothing is woken. applyTableConfig's clamp-and-wake pass would
        // resettle every piece on the table once per spinner click.
        const bool ringMoved = seats != cur.seats; // `cur` is live: read it first
        srv.world.setTableCosmetic(wh, seats);
        broadcastTable(srv);
        if (ringMoved)
            srv.playersDirty = true; // the ring moved: poses change, strays reseat
        if (srv.snaps.live) {
            captureSnapshot(srv);
            broadcastTimeMachine(srv);
        }
    }};
    // The table PLAN: the whole outline / seats / areas document at once, the way
    // a module author or an agent writes it (table_plan.cpp):
    //   {"type":"tableplan", "plan":{...}}                replace and apply
    //   {"type":"tableplan", "plan":{...}, "merge":true}  merge over the stored plan
    //   {"type":"tableplan", "reset":true}                forget it (areas go; outline and seats stay)
    // Same gate as tableShape. Answers {"type":"tableplanresult", ok, error?, warnings, ...}.

reg["tableshape"] = CommandSpec{Cap::Edit, false, false, false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        tw::TableConfig cfg = srv.world.table(); // copy: the live one is the world's
        cfg.plan.clear(); // drawn by hand from here on: a plan no longer describes this outline
        const json shape = msg.value("shape", json());
        if (shape.is_null()) {
            // Back to the plain rectangle. Both size fields are optional; absent
            // means "keep what the table measures now" (which, coming off a
            // shape, is that shape's AABB — the least surprising rectangle).
            // The bounds are the outline's own (see tableShapeFromJson): the
            // 0.1 mm int16 position encoding caps ANY table at ±3.2767 m.
            cfg.shape.reset();
            const float minHalf = kMinEditExtent / 2.0f;
            if (msg.contains("halfWidth") && msg["halfWidth"].is_number())
                cfg.halfWidth = std::clamp(msg["halfWidth"].get<float>(), minHalf, 3.0f);
            if (msg.contains("halfDepth") && msg["halfDepth"].is_number())
                cfg.halfDepth = std::clamp(msg["halfDepth"].get<float>(), minHalf, 3.0f);
            // Coming off a SHAPE with no size given, the rectangle inherits that
            // shape's AABB — which may predate the rule, so grow it rather than
            // leave the command as a way to keep an undersized table.
            cfg.halfWidth = std::max(cfg.halfWidth, minHalf);
            cfg.halfDepth = std::max(cfg.halfDepth, minHalf);
        } else {
            std::string err;
            std::optional<tw::TableShape> parsed = tableShapeFromJson(shape, err);
            if (!parsed) {
                c.replyError("err.tableShape", {{"reason", err}});
                return;
            }
            // The editor's own floor, checked here rather than in the parser: an
            // OLD table under it must still load (see kMinEditExtent), but nobody
            // may draw a new one. The client refuses this first (MIN_SPAN in
            // workbench/table.ts) — this is the untrusted-input half.
            if (parsed->maxX - parsed->minX < kMinEditExtent ||
                parsed->maxZ - parsed->minZ < kMinEditExtent) {
                c.replyError("err.tableShape",
                             {{"reason", "the table is under " +
                                             std::to_string(kMinEditExtent) + " m on one axis"}});
                return;
            }
            cfg.shape = std::move(*parsed);
        }
        // Objects are pushed back inside the new outline; the AUTHORED table
        // layer (zones, snap points, drawings, decals) is deliberately left
        // where it is, even if a piece of it now hangs over the void. Silently
        // moving someone's authoring is worse than leaving it visibly wrong —
        // they drew it, they can see it, and only they know where it should go.
        applyTableConfig(srv, std::move(cfg)); // rebuild statics, push pieces in, broadcast
        // Give the edit its own undo point immediately: the autosnapshot only
        // fires on a quiet table, and the first thing anyone does after
        // reshaping is reshape again.
        if (srv.snaps.live) {
            captureSnapshot(srv);
            broadcastTimeMachine(srv);
        }
    }};
    // The table's NON-geometric properties: how tall the rail is drawn and how
    // many players it is laid out for.
    //   {"type":"tableprops", "wallHeight":0.01, "seats":6}
    //
    // A message of its own rather than two more fields on `tableShape`: a patch
    // carrying only {wallHeight} would arrive there with no `shape` key, hit the
    // "back to the plain rectangle" branch and destroy a drawn contour.
    //
    // NOT readOnly, unlike `tablesurface` — both fields live in the snapshot
    // ring's table blob (tablePhysJson), so a rollback CAN undo them and forking
    // the future on an edit is the honest thing to do.

reg["tablesurface"] =
        CommandSpec{Cap::Edit, false, /*readOnly=*/true, /*vetoable=*/false, [](CommandContext& c) {
            TW_CMD_LOCALS(c);
            if (msg.value("reset", false)) {
                seedSurface(srv);
                applySurface(srv, json::object()); // no patch, just broadcast the seed
                return;
            }
            applySurface(srv, msg.contains("surface") ? msg["surface"] : json::object());
        }};
    // --- table editor: user-owned zones + snap points (ribbon "Стол" tools) ---
    // Persisted with the table; the ScriptEngine zone/snap callbacks rebroadcast.

reg["tabletaction"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        json* doc = tabletDocOf(srv, id());
        if (!doc)
            return;
        const std::string eid = msg.value("element", std::string());
        json* el = findElement(*doc, eid);
        if (!el)
            return;
        // Restricted elements are stripped from the broadcasts of players who
        // may not see them; a forged action on one must not work either.
        if (!elementVisibleTo(*el, tabletViewerFor(srv, player)))
            return;
        // Image input owns src rather than a numeric/text value. Only registered
        // raster assets are accepted, never URLs/data URLs or arbitrary paths.
        if (el->value("type", std::string()) == "imageInput") {
            if (msg.value("event", std::string("action")) != "action" ||
                !mayUseTabletImage(srv, player, id(), eid) || !msg.contains("value") ||
                !msg["value"].is_string()) return;
            const auto* obj = srv.world.object(id());
            if (!obj || msg.value("guid", std::string()) != obj->guid()) return;
            const std::string path = msg["value"].get<std::string>();
            const json* asset = assetFind(srv, path);
            if (!path.empty() && (!path.starts_with("library/assets/") ||
                !(path.ends_with(".png") || path.ends_with(".jpg") || path.ends_with(".jpeg") || path.ends_with(".webp")) ||
                !asset || asset->value("kind", std::string()) != "image" || asset->value("deleted", false))) return;
            if (el->value("src", std::string()) == path) return;
            const std::string action = el->value("action", std::string());
            c.beginMutation();
            (*el)["src"] = path;
            broadcastProps(srv, id());
            if (!action.empty()) srv.scripts.fireTabletActionText(id(), action, player, path, eid);
            return;
        }
        // A page navigator bound to the page list carries no value of its own:
        // a numeric action on it means "switch this side to page N". Scripts
        // that still poke a tabs element's value therefore keep working.
        if (el->value("bind", std::string()) == "pages" && msg.contains("value")
            && msg["value"].is_number()) {
            json* side = sideOf(*doc, el->value("side", 0));
            if (!side) return;
            auto pit = side->find("pages");
            if (pit == side->end() || !pit->is_array() || pit->empty()) return;
            const int n = std::clamp(msg["value"].get<int>(), 0,
                                     static_cast<int>(pit->size()) - 1);
            const std::string pid = (*pit)[static_cast<std::size_t>(n)].value("id", std::string());
            if (!pid.empty() && side->value("active", std::string()) != pid) {
                (*side)["active"] = pid;
                syncNavValues(*doc, el->value("side", 0));
                broadcastProps(srv, id());
            }
            const std::string fn = el->value("action", std::string());
            if (!fn.empty())
                if (srv.scripts.fireTabletAction(id(), fn, player, double(n), eid)) c.beginMutation();
            return;
        }
        // event selects which script callback fires: a plain action (click/value
        // change) vs. pointer hover/unhover. Only the action path owns a value.
        const std::string event = msg.value("event", std::string("action"));
        const char* fnField = event == "hover" ? "onHover"
                            : event == "unhover" ? "onUnhover" : "action";
        std::optional<double> value;
        std::optional<std::string> strValue; // text-input fields carry a string
        if (event == "action" && msg.contains("value")) {
            if (msg["value"].is_number()) {
                value = msg["value"].get<double>();
                (*el)["value"] = *value;   // server owns the control's value
                // Radio behaviour: a toggle in a `group` turning ON zeroes its
                // group siblings (mutual exclusion is server-owned). Keyed on the
                // TYPE, so `checkbox` — the other boolean — stays independent: a
                // set of checkboxes is not a radio group.
                if (*value != 0.0 && el->value("type", std::string()) == "toggle") {
                    const std::string grp = el->value("group", std::string());
                    if (!grp.empty())
                        for (json& e : (*doc)["elements"])
                            if (&e != el && e.is_object() &&
                                e.value("type", std::string()) == "toggle" &&
                                e.value("group", std::string()) == grp)
                                e["value"] = 0;
                }
                broadcastProps(srv, id()); // reflect the new value to everyone
            } else if (msg["value"].is_string()) {
                strValue = msg["value"].get<std::string>();
                (*el)["value"] = *strValue;
                broadcastProps(srv, id());
            }
        }
        const std::string action = el->value(fnField, std::string());
        if (!action.empty()) {
            if (strValue) {
                if (srv.scripts.fireTabletActionText(id(), action, player, *strValue, eid)) c.beginMutation();
            } else {
                if (srv.scripts.fireTabletAction(id(), action, player, value, eid)) c.beginMutation();
            }
        }
    }};
    for (const auto key : {"settabletdoc", "setpdf", "pdfpage", "setoverlay", "settabletpage", "tabletink", "tabletaction"})
        observeMutation(reg.at(key), objectMutationState);

}

} // namespace srv

reg["tabletink"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        json* doc = tabletDocOf(srv, id());
        if (!doc)
            return;
        json* side = sideOf(*doc, msg.value("side", 0));
        if (!side)
            return;
        if (!side->contains("ink") || !(*side)["ink"].is_array())
            (*side)["ink"] = json::array();
        json& ink = (*side)["ink"];
        const std::string op = msg.value("op", std::string("add"));

        if (op == "add") {
            auto sit = msg.find("stroke");
            if (sit == msg.end() || !sit->is_object())
                return;
            const json& s = *sit;
            const std::string sid = s.value("id", std::string());
            if (sid.empty())
                return;
            json pts = json::array();
            if (auto p = s.find("pts"); p != s.end() && p->is_array())
                for (const json& v : *p)
                    if (v.is_number()) pts.push_back(v.get<double>());
            // Rebuilt field by field rather than stored as sent: this is
            // player-authored content on a Cap::Play command, and `owner` in
            // particular decides who may erase it later.
            if (pts.size() < 4 || pts.size() % 2 != 0 || pts.size() > kMaxInkPoints)
                return;
            // The GM's draw-colour restriction covers this surface too, on the
            // same rule and the same exemption as the world draw tool
            // (commands_tableedit.cpp drawadd): otherwise "players may not choose
            // their colour" stops being true the moment anyone opens a tablet.
            // Raw seat hex, not the felt lift — a page is white, and that is also
            // what the client's own tablet default uses (ui.ts myInkColor).
            std::string color = s.value("color", std::string("#c02020"));
            if (!can(srv, player, Cap::Edit) && !srv.policy.drawColor) {
                auto pit = srv.players.find(player);
                if (pit != srv.players.end()) color = seatColorHex(pit->second.color);
            }
            json st = json::object();
            st["id"] = sid;
            st["page"] = (s.contains("page") && s["page"].is_string()) ? s["page"] : json(nullptr);
            st["color"] = std::move(color);
            st["width"] = std::clamp(s.value("width", 4.0), 0.5, 64.0);
            st["pts"] = std::move(pts);
            st["owner"] = player;
            if (ink.size() >= kMaxInkStrokes)
                ink.erase(ink.begin()); // a page of scribbles must not grow without bound
            ink.push_back(std::move(st));
        } else if (op == "del") {
            const std::string sid = msg.value("strokeId", std::string());
            const auto gone = std::remove_if(ink.begin(), ink.end(), [&](const json& s) {
                return s.is_object() && s.value("id", std::string()) == sid && mayErase(srv, player, s);
            });
            if (gone == ink.end())
                return;
            ink.erase(gone, ink.end());
        } else if (op == "clear") {
            // Wiping someone else's work is a manager/GM action, unlike erasing
            // a single stroke you drew.
            if (!(can(srv, player, Cap::Admin) || isGm(srv, player)))
                return;
            const std::string page = msg.value("page", std::string());
            if (page.empty()) {
                if (ink.empty()) return;
                ink = json::array();
            } else {
                const auto gone = std::remove_if(ink.begin(), ink.end(), [&](const json& s) {
                    return s.is_object() && s.value("page", std::string()) == page;
                });
                if (gone == ink.end()) return;
                ink.erase(gone, ink.end());
            }
        } else {
            return;
        }
        broadcastProps(srv, id());
    }};

    // A player interacted with an element on a tablet's face: `id` = the tablet
    // object, `element` = the element id, `value` (optional) = its new value for
    // value-bearing controls (counter/slider). Server-owned value updates are
    // written back to the doc + rebroadcast, then the element's `action` (a Lua
    // function name on the tablet's own script) is fired as fn(player,value,id).

reg["throw"] = CommandSpec{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!heldByOther()) {
            // Don't trust client velocities: cap linear/angular speed so a
            // bad client can't fling objects through walls or stress physics.
            srv.world.throwObject(
                id(), clampLen(vecFromJson(msg.value("v", json())), tw::tune::kMaxThrowSpeed),
                clampLen(vecFromJson(msg.value("w", json())), tw::tune::kMaxThrowSpin),
                std::uint32_t(msg.value("ks", 0.0)));
            // Same pack grace as the release path above — a flick applied to a
            // whole selection arrives as one command per member.
            srv.world.joinThrowPack(id(), player);
            achievementThrow(srv, player, id(), msg);
                lookaheadOnThrow(srv, id()); // future records to laggy clients (thrower incl.)
            srv.scripts.fireEvent(id(), "flick", player); // TTS onFlick / onObjectFlick
        }
    }};

reg["thumbpurge"] = CommandSpec{Cap::Admin, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        namespace fs = std::filesystem;
        const std::size_t n = srv.thumbIndex.size();
        const fs::path dir = srv.libraryDir / "thumbs";
        std::error_code ec;
        fs::remove_all(dir, ec);
        fs::create_directories(dir, ec);
        srv.thumbIndex.clear();
        srv.thumbBytes = 0;
        reply(json{{"type", "thumbresult"}, {"ok", true}, {"purged", n}}.dump());
    }};

    // ---- custom effects library (Effects workbench) -----------------------
    // The server is a dumb sync/persist/export layer here: it stores the opaque
    // client-owned `spec` (particle params or shader source) plus name/category,
    // and never interprets it. Objects reference an effect by id ({"ref":...} in
    // their Visual.vfx); the client resolves it against this library at render
    // time, so an edit shows up on every referencing object. Delete is a
    // soft-delete (deleted=true → bin, restorable); purge removes it for good.

reg["timemachine"] = CommandSpec{Cap::Edit, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Roll the whole table back to a stored snapshot (authoritative for all).
        const std::size_t idx = msg.value("index", std::size_t(0));
        restoreSnapshot(srv, idx);
        broadcastTimeMachine(srv);
    }};

reg["tmstats"] = CommandSpec{Cap::None, false, true, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Debug: snapshot count vs distinct COW blobs (shared ptrs).
        std::set<const std::string*> uniq;
        for (const auto& s : srv.snaps.ring)
            for (const auto& [oid, blob] : s.objs) uniq.insert(blob.get());
        reply(json{{"type", "tmstats"}, {"snapshots", srv.snaps.ring.size()},
                   {"uniqueBlobs", uniq.size()}}
                  .dump());
    }};
    // --- workbench edit leases -------------------------------------------------
    // One editor at a time per workbench asset. `key` is opaque (the client's
    // naming scheme: "obj:<tmpl>", "effect:<id>", "material:<id>", "asset:<path>",
    // "table") — the server only checks that it is one short line, so adding an
    // editable thing later needs no server change. The block is HARD: a busy key
    // is refused to everyone, Owner included; a lease goes away on release, on
    // disconnect (ws_session close) or on the TTL, never by being taken.
    // readOnly=true because a lease changes nothing about the table and must not
    // fork the time machine; vetoable=false keeps scripts out of a bookkeeping call.

reg["tokenset"] = CommandSpec{Cap::Edit, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        auto* object=c.obj();if(!object||object->kind()!=tw::ObjectKind::Prop){c.replyError("token.propOnly");return;}
        const auto patch=msg.find("token");if(patch==msg.end()||!patch->is_object()){c.replyError("token.invalid");return;}
        const auto found=srv.visuals.find(id());
        json next=found!=srv.visuals.end()&&found->second.token.is_object()?found->second.token:json::object();
        for(auto it=patch->begin();it!=patch->end();++it)next[it.key()]=it.value();
        const json clean=sanitizeToken(next);if(!clean.is_object()){c.replyError("token.invalid");return;}
        c.beginMutation();
        const float bottom=object->position().y-object->halfExtents().y;
        json snap=objectSnapshotJson(srv,object);auto&visual=snap["visual"];
        visual["token"]=clean;visual["collider"]=tokenColliderJson(clean);
        visual.erase("stand");visual.erase("pawn");visual.erase("model");visual.erase("modelRotation");
        replaceObjectFromJson(srv,id(),snap);
        if(auto* updated=srv.world.object(id())){auto pos=updated->position();pos.y=std::max(0.0f,bottom)+updated->halfExtents().y;updated->setPosition(pos);}
        broadcastProps(srv,id());
        json response = {{"type", "tokenresult"}, {"id", id()}, {"ok", true}};
        if(msg.contains("requestId"))response["requestId"]=msg["requestId"];reply(response.dump());
    }};

reg["toss"] = CommandSpec{Cap::Play, true, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (!heldByOther()) {
            // Optional client-rolled toss (the flick w/ks precedent): the client
            // predicts its own toss, so it must know the exact impulse. Clamped
            // to the same envelope the server rolls from — a hostile client
            // cannot exceed what srv.frand could have rolled anyway — and absent
            // fields keep the legacy server-rolled behaviour byte for byte.
            // vy stays server-fixed: the pop height is the toss's game-design
            // envelope, only the horizontal scatter and the tumble are rolled.
            tw::Vec3 v{srv.frand(-0.3f, 0.3f), 2.2f, srv.frand(-0.3f, 0.3f)};
            if (msg.contains("vx") || msg.contains("vz")) {
                v.x = std::clamp(float(msg.value("vx", 0.0)), -0.3f, 0.3f);
                v.z = std::clamp(float(msg.value("vz", 0.0)), -0.3f, 0.3f);
            }
            tw::Vec3 w{srv.frand(-15, 15), srv.frand(-15, 15), srv.frand(-15, 15)};
            if (msg.contains("w")) {
                const tw::Vec3 cw = vecFromJson(msg["w"]);
                w = {std::clamp(cw.x, -15.0f, 15.0f), std::clamp(cw.y, -15.0f, 15.0f),
                     std::clamp(cw.z, -15.0f, 15.0f)};
            }
            // `ks` (v8, as flick/release): the client's per-throw kick seed. Its
            // prediction draws the first-impact jitter from the same
            // ThrowKickRng; ks == 0 keeps the server-RNG path (deterministic
            // between scratch and real since World::applyImpacts sorts its drain).
            srv.world.throwObject(id(), v, w, std::uint32_t(msg.value("ks", 0.0)));
            achievementThrow(srv, player, id(), msg);
                lookaheadOnThrow(srv, id()); // future records to laggy clients (thrower incl.)
            srv.scripts.fireEvent(id(), "randomize", player);
        }
    }};
