reg["ungroup"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        if (auto g = srv.world.groupOf(id())) {
            const auto members = srv.world.groupMembers(*g);
            srv.world.ungroup(*g);
            broadcastGroups(srv);
            for (tw::ObjectId mid : members) srv.scripts.fireEvent(mid, "ungroup", player);
        }
    }};
    // Clipboard: copy/cut a set of objects into the player's clipboard (full
    // snapshots + offsets from the centroid + group ids), paste full clones.
    auto fillClipboard = [](Server& srv, tw::PlayerId player, const json& msg) {
        auto& clip = srv.clipboard[player];
        clip.clear();
        std::vector<std::pair<const tw::Object*, tw::Vec3>> picked;
        tw::Vec3 c{0, 0, 0};
        if (msg.contains("ids") && msg["ids"].is_array())
            for (const auto& v : msg["ids"]) {
                const tw::Object* o = srv.world.object(v.get<tw::ObjectId>());
                if (o) { picked.push_back({o, o->position()}); c.x += o->position().x; c.y += o->position().y; c.z += o->position().z; }
            }
        if (!picked.empty()) { c.x /= picked.size(); c.y /= picked.size(); c.z /= picked.size(); }
        for (auto& [o, p] : picked)
            clip.push_back({objectSnapshotJson(srv, o).dump(),
                            tw::Vec3{p.x - c.x, p.y - c.y, p.z - c.z},
                            srv.world.groupOf(o->id()).value_or(0)});
    };

reg["unhand"] = CommandSpec{Cap::Play, false, false, true, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        // Play a card out of your hand: it lands face-up just in front of you.
        auto ho = srv.handOwner.find(id());
        if (ho != srv.handOwner.end() && ho->second == player && srv.players.count(player)) {
            c.beginMutation();
            srv.handOwnerErase(id()); // keeps handNonCards in sync (iterator dies here)
            srv.scripts.fireEvent(id(), "leaveHand", player);
            const SeatPose sp = seatPoseFor(srv, srv.players[player].seat);
            // Same inward axis as arrangeHand: taken from the yaw, not from the
            // seat's position vector. They agree on a round-robin seat and differ
            // on a zone-derived one, which is not radial.
            const float inx = std::sin(sp.yaw), inz = std::cos(sp.yaw);
            const tw::Vec3 out{sp.x + inx * 0.30f, 0.02f, sp.z + inz * 0.30f};
            tw::Object* o = srv.world.object(id());
            if (o && o->kind() != tw::ObjectKind::Card) {
                o->setPosition({out.x, std::max(o->position().y, 0.02f), out.z});
                o->setLinearVelocity({});
                o->setAngularVelocity({});
            } else {
                srv.world.placeCard(id(), out, sp.yaw, /*faceUp=*/true);
            }
            arrangeHand(srv, player); // re-fan the rest
            sendReveals(srv);
        }
    }};

reg["view"] = CommandSpec{Cap::Play, false, /*readOnly=*/true, /*vetoable=*/false, [](CommandContext& c) {
        TW_CMD_LOCALS(c);
        const tw::Object* o = srv.world.object(id());
        if (!o) return;
        const auto* card = dynamic_cast<const tw::Card*>(o);
        auto vit = srv.visuals.find(id());
        const bool concealable = card != nullptr ||
                                 (vit != srv.visuals.end() && vit->second.concealable);
        json out = {{"type", "viewobj"}, {"id", id()}, {"ok", true}};
        if (concealable) {
            tw::PlayerId zoneOwner = 0;
            std::vector<tw::ScriptEngine::HiddenAssignment> assigns;
            srv.scripts.hiddenAssignments(assigns);
            for (const auto& a : assigns)
                if (a.obj == id()) { zoneOwner = a.owner; break; }
            auto ho = srv.handOwner.find(id());
            const tw::PlayerId handOwner = ho != srv.handOwner.end() ? ho->second : 0;
            if ((zoneOwner && zoneOwner != player) || (handOwner && handOwner != player)) {
                out["ok"] = false;
                out["reason"] = "hidden"; // someone else's hidden zone / hand
                reply(out.dump());
                return;
            }
            const bool privateView = handOwner == player || zoneOwner == player;
            if (!privateView) // public concealable: everyone sees who looks
                publish(srv, Chan::State,
                        json{{"type", "viewing"}, {"id", id()}, {"player", player}}.dump());
        }
        if (card) out["code"] = card->code(); // the front the viewer may now see
        reply(out.dump());
    }};
